    public String sharesFormatDate(String Date) {

        String date = Date.substring(0, 2);
        int departdate = Integer.parseInt(date);

        String DateFormatted = gl.plusDaysFromTodayNew(departdate);
        LocalDateTime departuredate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
        return DateUtil.formatDateToSharesDateFormat(departuredate.toLocalDate());

    }

    public String sharesFormatDate1(String Date) {

        String date = Date.substring(0, 2);
        int departdate = Integer.parseInt(date);

        String DateFormatted = gl.plusDaysFromTodayNew(departdate);
        LocalDateTime departuredate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
        return DateUtil.formatDateToISharesDateFormat(departuredate.toLocalDate());

    }

