    public void restrictFlight(ExtentTest logInfo, String FlightNo, String departureDate, String OriginCity) {

        try {

            //6:CR360/06DECPTY
            String command = "6:" + "CR" + FlightNo + "/" + sharesFormatDate(departureDate) + OriginCity;
            gl.logCommand(logInfo,command);
            gl.sendCmdValidateResponse(command,logInfo);

            String response = isharesPageObjects1.SHARES_RESPONSE.getText();
            if (response.contains("148SHIP NOT ASSIGNED")) {

                openFlight(logInfo, FlightNo, sharesFormatDate(departureDate), OriginCity);
                isharesPageObjects1.FORMSIZE_DROPDOWN.click();
                isharesPageObjects1.FORMSIZE_SELECT1.click();

            }
            gl.logCommand(logInfo,command);
            gl.sendCmdValidateResponse(command,"FLT  " + FlightNo + " RESTRICTED  ","ASSIGNED CONTROLLING SET FOR " + OriginCity,logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }

    }


