    public void openFlight(ExtentTest logInfo, String FlightNo, String departureDate, String OriginCity) {

        try {
            isharesPageObjects1.FORMSIZE_DROPDOWN.click();
            isharesPageObjects1.FORMSIZE_SELECT2.click();
            gl.waitForProfileLoad();

            String command = "6:*A" + FlightNo + "/" + departureDate + OriginCity;
            gl.logCommand(logInfo,command);
            gl.sendCmdForForm2ValidateResponse(command,logInfo);

            if (!isharesPageObjects1.SHARES_RESPONSE.getText().contains("SHIP ASSIGNED")) {
                String EqpNumber;
                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                EqpNumber = response.substring(response.indexOf(FlightNo) + 4,response.indexOf(FlightNo) + 10).trim();

                String command2 = "6:I*F" + EqpNumber;
                gl.logCommand(logInfo,command2);
                gl.sendCmdForForm2ValidateResponse(command2,logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                String FleetNumber = "";

                if(globalConstants.testEnv.equalsIgnoreCase("sharesCURL")){
                    FleetNumber = isharesPageObjects1.SHARES_RESPONSE.getText().substring(128, 132);
                }
                else{
                    FleetNumber = isharesPageObjects1.SHARES_RESPONSE.getText().substring(130, 134);
                }

                String command3 = "6:CA" + departureDate + "\n" + FlightNo + OriginCity + FleetNumber;
                gl.logCommand(logInfo,command3);
                isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA.click();
                gl.copyCmdToClipboardAndPaste(command3,isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);
                isharesPageObjects1.SEND_ISHARES.click();
                gl.waitForProfileLoad();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                response = isharesPageObjects1.SHARES_RESPONSE.getText();
                gl.logResponse(logInfo,response);
                Assert.assertTrue(response.contains("SHIP ASSIGNED"));
            }

            if (isharesPageObjects1.SHARES_RESPONSE.getText().contains("SHIP ASSIGNED")) {
                System.out.println("SHIP ASSIGNED SUCCESSFULLY: " + FlightNo);
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


