    public void searchavailabilityTwoDifferentClasses(ExtentTest logInfo, String Origin, String Destination, String date, String totalpax, String airline, String COS2, String COS1, String PNRType) {
        String command = null;
        try {
            //A PTYLAX 10NOV-CM
            String Date = date.substring(0, 2);
            int departdate = Integer.parseInt(Date);
            int flag = 0;

            String command2 = null;
            String command3 = null;

            for (int i = departdate; i <= 5; i++) {  // loop for date

                String DateFormatted = gl.plusDaysFromTodayNew(i);
                LocalDateTime departuredate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
                String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departuredate.toLocalDate());

                mSharesStartDateSegOne.put(getDriverID(), i); //storing this value to check Other segment date should be greater than this date
                System.out.println(DateFormatted + "Date in map");
                mFlightDepartDate.put(getDriverID(), DateFormatted);

                if (airline.equalsIgnoreCase("CM")) {
                    command = "A " + Origin + Destination + " " + departureDateFormatted + "-" + "CM";
                } else if (airline.equalsIgnoreCase("UA")) {
                    command = "A " + Origin + Destination + " " + departureDateFormatted + "-" + "UA";
                } else if (airline.equalsIgnoreCase("Redemption")) {
                    command = "A " + Origin + Destination + " " + departureDateFormatted + "/" + "R";
                }
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,logInfo);

                String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                gl.checkForErrors(command,Response,logInfo);


                Flight:  for (int j = 1; j <= 3; j++) {  //loop for flight

                    if(PNRType.equalsIgnoreCase("Group")){
                        command2 = "N" + totalpax + COS2 + j + "GNN"; //N2Y1
                    }
                    else if (PNRType.equalsIgnoreCase("NRSA")) {
                        command2 = "N" + totalpax + COS2 + j + "MM";
                    }
                    else if (PNRType.equalsIgnoreCase("WaitList")) {
                        command2 = "N" + totalpax + COS2 + j + "PD";
                    }
                    else if (PNRType.equalsIgnoreCase("NRPS")) {
                        command2 = "N" + totalpax + COS2 + j + "PNN";
                    }
                    else {
                        command2 = "N" + totalpax + COS2 + j; //N2Y1
                    }

                    gl.logCommand(logInfo,command2);
                    gl.sendCmdValidateResponse(command2,logInfo);

                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    gl.checkForErrors(command2,response,logInfo);

                    if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") || response.contains("SS" + totalpax) || response.contains("NN" + totalpax)) {
                        gl.ignoreTRNS(logInfo);
                        gl.sendCmdValidateResponse(command,logInfo);

                        if(PNRType.equalsIgnoreCase("Group")){
                            command3 = "N" + totalpax + COS2 + j + "GNN"; //N2Y1
                        }
                        else if (PNRType.equalsIgnoreCase("NRSA")) {
                            command3 = "N" + totalpax + COS2 + j + "MM";
                        }
                        else if (PNRType.equalsIgnoreCase("WaitList")) {
                            command3 = "N" + totalpax + COS2 + j + "PD";
                        }
                        else if (PNRType.equalsIgnoreCase("NRPS")) {
                            command3 = "N" + totalpax + COS2 + j + "PNN";
                        }
                        else {
                            command3 = "N" + totalpax + COS2 + j; //N2Y1
                        }

                        gl.sendCmdValidateResponse(command3,logInfo);     //Now it will take the original class
                        gl.checkForErrors(command3,isharesPageObjects1.SHARES_RESPONSE.getText(),logInfo);

                        if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") || response.contains("SS" + totalpax)){

                            mFlightNumber.put(getDriverID(), response.substring(6, 10).trim());
                            System.out.println("FFlight number " + response.substring(6, 10));

                            flag = 1;
                            break;
                        }
                        else{
                            gl.logCommand(logInfo,command);
                            gl.sendCmdValidateResponse(command,logInfo);

                            Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                            gl.checkForErrors(command,Response,logInfo);
                            continue Flight;
                        }
                    }
                    else if(response.contains("NO MORE FOR DISPLAY") || response.contains("AVAIL DISP ABSENT-REDISP MSG")){
                        gl.logCommand(logInfo,command);
                        gl.sendCmdValidateResponse(command,logInfo);

                        gl.checkForErrors(command,isharesPageObjects1.SHARES_RESPONSE.getText(),logInfo);
                    }
                }

                if (flag == 1) {
                    break;
                }
            }
            mOriginCity.put(getDriverID(), Origin);
            mDestinationcity.put(getDriverID(), Destination);

            logInfo.pass("Search for availability for first segment");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

