    public void openNewCopaWindow(ExtentTest logInfo) {
        try {

            String currentID = getDriver().getWindowHandle();

            CurrentwindowID.put(getDriverID(), currentID);

            String newtab = "window.open('about:blank','_blank');";
            ((JavascriptExecutor) getDriver()).executeScript(newtab);

            Set<String> handles = getDriver().getWindowHandles();

            for (String actual : handles) {
                if (!actual.equalsIgnoreCase(currentID)) {

                    if (globalConstants.testEnv.equalsIgnoreCase("SIT")) {
                        getDriver().switchTo().window(actual);
                        getDriver().get(globalConstants.UAT);

                    } else {
                        getDriver().switchTo().window(actual);
                        getDriver().get(globalConstants.SIT);

                    }
                }
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

