    public void enterSpecificPassengerDetails(ExtentTest logInfo, String Fname, String Lname,String FFPax,String FFnumber) {

        int totalpaxCount = 1;
        int paxcount = totalpaxCount;
        ArrayList<String> PaxNameList = new ArrayList<>();
        ArrayList<String> FQTVFnameList = new ArrayList<>();

        String[] TotalPax = new String[1];
        TotalPax[0] = "Adult";

        Faker faker = new Faker(new Locale("en-US"));
        FName = new String[paxcount];
        mFName.put(getDriverID(), FName);
        PassengerName = new String[paxcount];
        PassengerLastName = new String[paxcount];
        DOB = new String[paxcount];
        mDOB.put(getDriverID(), DOB);
        LName = new String[paxcount];
        mLName.put(getDriverID(), LName);
        mPaxType.put(getDriverID(), TotalPax);
        isNonRevenue.put(getDriverID(), false);


        try {
            String command;
            //-GAYLE/SWAM*
            FName[0] = Fname;
            LName[0] = Lname;
            DOB[0] = gl.generateDateOfBirth("ADT");
            FQTVFnameList.add(Fname);

            mPaxName.put(FName[0].toUpperCase(), "Adult");

            if(FFPax.equalsIgnoreCase("true")){

                command = "-" + FName[0] + "/" + LName[0]+"*" + FFnumber;
            } else{
                command = "-" + FName[0] + "/" + LName[0];

            }
            gl.logCommand(logInfo,command.toUpperCase());
            gl.sendCmdValidateResponse(command,FName[0].toUpperCase(),LName[0].toUpperCase(),logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            logInfo.pass("I am entering pax details");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }

        mFName.put(getDriverID(), FName);
        mLName.put(getDriverID(), LName);
        mDOB.put(getDriverID(), DOB);
        mPaxName_PaxType.put(getDriverID(),mPaxName);
        mPaxNameList.put(getDriverID(), PaxNameList);
        FQTVFname.put(getDriverID(),FQTVFnameList);
        System.out.println("mFname size " + mFName.get(getDriverID()).length);

    }

