    public void navigateUrl(ExtentTest logInfo)
    {


        try {
            if(globalConstants.testEnv.equalsIgnoreCase("sharesURL")){
                url = globalConstants.sharesURL;
                getDriver().get(url);
                misSharesCase.put(getDriverID(),Boolean.TRUE);
            }else if(globalConstants.testEnv.equalsIgnoreCase("sharesCURL")){
                url = globalConstants.sharesCURL;
                getDriver().get(url);
                misSharesCase.put(getDriverID(),Boolean.TRUE);
            }else if(globalConstants.testEnv.equalsIgnoreCase("sharesD3URL")){
                url = globalConstants.sharesD3URL;
                getDriver().get(url);
                misSharesCase.put(getDriverID(),Boolean.TRUE);
            }else if(globalConstants.testEnv.equalsIgnoreCase("VP1SHCURL")){
                url = globalConstants.VP1SHCURL;
                getDriver().get(url);
                misSharesCase.put(getDriverID(),Boolean.TRUE);
            }
            gl.waitForElementAfterReload(getDriver(), isharesPageObjects1.USERID, PAGE_LOAD_TIMEOUT);
        } catch (AssertionError | Exception e) {

            String exception = "ERR_CONNECTION_TIMED_OUT. The site cant be reached. Connection was rest. Failed due to "+e;
            mFailureDescription.put(getDriverID(),exception);
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }

    public String generateBlankSpace(int size) {
        String temp = "";
        int len = 40 - size;
        for (int i = 1; i <= len; i++) {
            temp = temp + " ";
        }
        return temp;
        //NOTE: No of blank spaces are very important, otherwise the transaction will not be accepted
    }

    public String getSharesDate() {
        String DateFormatted = gl.plusDaysFromTodayNew(mSharesStartDateSegOne.get(getDriverID()));
        LocalDateTime departuredate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
        return DateUtil.formatDateToSharesDateFormat(departuredate.toLocalDate());

    }

