    public String addSpecificDestination(String origin, int paxIndex, String totalBag,String Weight,int tagNum) {
        gl.waitForProfileLoad();
        isharesPageObjects1.FORMSIZE_DROPDOWN.click();
        isharesPageObjects1.FORMSIZE_SELECT24.click();
//         6:120/08AUGPTY-AMMERA/BULIO
//         B1/10-CM556743.MEX

        int TotalBag = Integer.parseInt(totalBag);
        String TagNum = String.valueOf(tagNum);

        while (TotalBag>1){
            int x = (int)((Math.random() * (555555 - 111111)) + 222222);
            TagNum = TagNum + "/" + x;
            TotalBag--;
        }

        String cmd = null;
        if (mPaxType.get(getDriverID())[paxIndex].equalsIgnoreCase("Adult")){

            cmd = "6:" + mFlightNumber.get(getDriverID())
                    + "/" + getSharesDate()
                    + origin + "-" + mFName.get(getDriverID())[paxIndex]
                    + "/" + mLName.get(getDriverID())[paxIndex] + "\n"
                    + "B" + totalBag + "/" + Weight + "-" + TagNum
                    + "." + mDestinationcity.get(getDriverID());

        }else if (mPaxType.get(getDriverID())[paxIndex].equalsIgnoreCase("Child")){

            cmd = "6:" + mFlightNumber.get(getDriverID())
                    + "/" + getSharesDate()
                    + origin + "-" + mFName.get(getDriverID())[paxIndex]
                    + "/" + mLName.get(getDriverID())[paxIndex] + "\n"
                    + "B" + totalBag + "C1/" + Weight + "-" + TagNum
                    + "." + mDestinationcity.get(getDriverID());
        }
        System.out.println(cmd);
        return cmd;
    }



