    public boolean validatePrimaryADC(String ADCInfo, ExtentTest logInfo) throws IOException {

        isharesPageObjects1.INPUT_TEXT_AREA_ROWS24.click();
        isharesPageObjects1.INPUT_TEXT_AREA_ROWS24.sendKeys(Keys.chord(Keys.CONTROL + "a" + Keys.BACK_SPACE));

        gl.copyCmdToClipboardAndPaste(ADCInfo, isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);
        isharesPageObjects1.SEND_ISHARES.click();

        gl.waitForProfileLoad();

        String response = isharesPageObjects1.SHARES_RESPONSE.getText();

        if (response.contains("DOCTYPE: P-PASSPORT") || response.contains("INFANT") || response.contains("SEATS ASSIGNED") || response.contains("CABIN STBY") || response.contains("DOCTYPE: A-ALIEN CARD") || response.contains("END OF API COLLECT MODE") || response.contains("BIRTHPLC INFORMATION")) {
            gl.scrollPageDown();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            return true;
        } else {
            gl.scrollPageDown();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            return false;
        }

    }

