    public void adjustSegment(ExtentTest logInfo,String AdjustType, String segSequence) {

        try {

            gl.logCommand(logInfo,saveAndRetrieve);
            gl.sendCmdValidateResponse(saveAndRetrieve,logInfo);

            String retrieve = "ER";
            gl.sendCmdIfRequired(retrieve, "PNR MODIFIED",mOrderNumber.get(getDriverID()),logInfo);
            gl.logCommand(logInfo,retrieve);

            gl.sendCmdIfRequired(retrieve,"PNR MODIFIED",logInfo);
            gl.logCommand(logInfo,retrieve);

            if (AdjustType.equalsIgnoreCase("ChangeFlightSegment")) {
//            T-ET*.S01/226/10JUL#I
                String AdjustCmd = "T-ET*.S0" + segSequence + "/" + mAltFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mAltrFlightDays.get(getDriverID())) + "|I";
                gl.logCommand(logInfo, AdjustCmd);
                gl.sendCmdValidateResponse(AdjustCmd, "OK",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                gl.sendCmdValidateResponse("*ET", "INVOL ",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                //Checking PNR history
                gl.sendCmdValidateResponse(checkPnrHistory,logInfo);
                gl.logCommand(logInfo,checkPnrHistory);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                //Check Ticket Status
                gl.sendCmdValidateResponse(checkTicketStatus, "INVOL",logInfo);
                gl.logCommand(logInfo,checkTicketStatus);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            }
            else if (AdjustType.equalsIgnoreCase("ChangeCOSAllSeg")) {
//            T-ET*.S05#L
                String AdjustCmd = "T-ET*.S0" + segSequence + "|L";
                gl.sendCmdValidateResponse(AdjustCmd, "OK",logInfo);
                gl.logCommand(logInfo, AdjustCmd);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                gl.sendCmdValidateResponse("*ET", "INVOL ",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            }

            gl.sendCmdValidateResponse("IR",logInfo);
            gl.sendCmdValidateResponse("*"+mOrderNumber.get(getDriverID()),mOrderNumber.get(getDriverID()),logInfo);
        }

        catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }

    }

