    public void changeSegStatus(ExtentTest logInfo,String TotalSegments,String Totalpax,String status) {

        int totalseg = Integer.parseInt(TotalSegments);
        int totalPax = Integer.parseInt(Totalpax);

        try {

            if (status.equalsIgnoreCase("USED")) {

                for (int i = 1; i <= totalseg; i++) {

                    for (int j = 1; j <= totalPax; j++) {

                        String SegStatusCmd = "T-ET/STATUS/" + status + "/" + j + "." + i + "*";
                        gl.sendCmdValidateResponse(SegStatusCmd, "OK",logInfo);

                        String retrieve = "*ET";
                        gl.sendCmdValidateResponse(retrieve, status,logInfo);
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    }
                }

            }else if (status.equalsIgnoreCase("PD")) {

                String command = "W" + sharesLNIATA.get(getDriverID()) + "*";
                gl.sendCmdValidateResponse(command,logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                String command1 = "ZAFIL CM E0381CE5 0B6 D7";
                gl.sendCmdValidateResponse(command1,logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                String command2 = "ZAFIL CM E0381CE5 0B7 C4";
                gl.sendCmdValidateResponse(command2,logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *","PD",logInfo);
                gl.sendCmdIfRequired(endAndretrieve,"PD",logInfo);

                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            }else if (status.equalsIgnoreCase("PRINTED")) {

                for (int i = 1; i <= totalseg; i++) {

                    for (int j = 1; j <= totalPax; j++) {

                        String SegStatusCmd = "T-ET/STATUS/" + status + "/" + j + "." + i + "*";
                        gl.logCommand(logInfo, SegStatusCmd);
                        gl.sendCmdValidateResponse(SegStatusCmd, "OK", logInfo);

                        String retrieve = "*ET";
                        gl.logCommand(logInfo, retrieve);
                        gl.sendCmdValidateResponse(retrieve, status, "STATUS", logInfo);
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    }
                }
            }
            } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 

        }
    }

