    public void printBoardingPass(ExtentTest logInfo,String BoardingType){

        try {
            //6:BF243/27JANPTY-YOU/YOURS
            if(BoardingType.equalsIgnoreCase("ForceBoarding")){
                for(int i=0;i<mFName.get(getDriverID()).length;i++) {
                    String Command = "6:BF" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                            + mOriginCity.get(getDriverID()) + "-" + mFName.get(getDriverID())[i] + "/" + mLName.get(getDriverID())[i];

                    gl.logCommand(logInfo,Command);
                    gl.sendCmdValidateResponse(Command,mFName.get(getDriverID())[i].toUpperCase(),logInfo);
                    logInfo.pass("PRINT BOARDING PASSES ");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    if (!Response.contains("BOARDING PASSES ISSUED")){
                        gl.sendCmdValidateResponse("MD","BOARDING PASSES ISSUED",logInfo);
                    }
                }
            }
            else if(BoardingType.equalsIgnoreCase("BoardingForUnCheckPax")){
                for(int i=0;i<mFName.get(getDriverID()).length;i++) {
                    String Command = "6:BF" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                            + mOriginCity.get(getDriverID()) + "-" + mFName.get(getDriverID())[i] + "/" + mLName.get(getDriverID())[i];

                    gl.logCommand(logInfo,Command);
                    gl.sendCmdValidateResponse(Command,mFName.get(getDriverID())[i].toUpperCase(),logInfo);
                    logInfo.pass("PRINT BOARDING PASSES ");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    if (Response.contains("BOARDING PASSES ISSUED")){
                        Assert.fail();
                    }
                }
            }
            else if(BoardingType.equalsIgnoreCase("InvalidBoarding")){
                for(int i=0;i<mFName.get(getDriverID()).length;i++) {
                    String Command = "6:BF" + mFlightNumber.get(getDriverID()) + "/" + mSharesStartDateSegOne.get(getDriverID())
                            + mOriginCity.get(getDriverID()) + "-" + mFName.get(getDriverID())[i] + "/" + mLName.get(getDriverID())[i];

                    gl.logCommand(logInfo,Command);
                    gl.sendCmdValidateResponse(Command,"INVLD",logInfo);
                    logInfo.pass("PRINT BOARDING PASSES ");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }
            }
            else if(BoardingType.equalsIgnoreCase("ThruBoarding")){
                for(int i=0;i<mFName.get(getDriverID()).length;i++) {
                    String Command = "6:BF" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                            + mOriginCity.get(getDriverID()) + "-" + mFName.get(getDriverID())[i] + "/" + mLName.get(getDriverID())[i];

                    gl.logCommand(logInfo,Command);
                    gl.sendCmdValidateResponse(Command,mFName.get(getDriverID())[i].toUpperCase(),logInfo);
                    logInfo.pass("PRINT BOARDING PASSES ");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    if (!Response.contains("2 BOARDING PASSES ISSUED")){
                        gl.sendCmdValidateResponse("MD","2 BOARDING PASSES ISSUED",logInfo);
                    }
                }
            }
            else if(BoardingType.equalsIgnoreCase("TestBoarding")){
                String TestBoarding = "6:BT" ;
                gl.logCommand(logInfo,TestBoarding);
                gl.sendCmdValidateResponse(TestBoarding,"TEST BOARDING PASS SENT",logInfo);
                logInfo.pass("TEST BOARDING PASS ");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }

    }

