    public void enterMultiSurnamesPassengerDetails_Shares(ExtentTest logInfo, String[] paxtype) {

        int totalpaxCount = paxtype.length;
        Faker faker = new Faker(new Locale("en-US"));
        FName = new String[totalpaxCount];
        mFName.put(getDriverID(), FName);
        PassengerName = new String[totalpaxCount];
        PassengerLastName = new String[totalpaxCount];
        DOB = new String[totalpaxCount];
        mDOB.put(getDriverID(), DOB);
        LName = new String[totalpaxCount];
        mLName.put(getDriverID(), LName);
        mPaxType.put(getDriverID(), paxtype);
        isNonRevenue.put(getDriverID(),false);
        ArrayList<String> PaxNameList = new ArrayList<>();

        String fname = faker.name().firstName().replaceAll("[^a-zA-Z0-9]", "");

        try {
            for (int j = 0; j < totalpaxCount; j++) {
                if (paxtype[j].equalsIgnoreCase("Adult")) {
                    FName[j] = fname;
                    LName[j] = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "");
                    DOB[j] = gl.generateDateOfBirth("ADT");
                    mPaxName.put(FName[j].toUpperCase(), "Adult");
                    String command = "-" + FName[j] + "/" + LName[j];
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.click();
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.sendKeys(command);
                    isharesPageObjects1.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    Assert.assertTrue(response.contains(FName[j].toUpperCase()) && response.contains(LName[j].toUpperCase()));
                } else if (paxtype[j].equalsIgnoreCase("MultiInitialAdult")) {
                    //-SWAN/KAM*-CHD06
                    FName[j] = faker.name().firstName().replaceAll("[^a-zA-Z0-9]", "");
                    LName[j] = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "");
                    DOB[j] = gl.generateDateOfBirth("Adt");
                    mPaxName.put(FName[j].toUpperCase(), "Adult");
                    String command = "-" + FName[j] + "/" + LName[j] ;
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.click();
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.sendKeys(command);
                    isharesPageObjects1.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    Assert.assertTrue(response.contains(FName[j].toUpperCase()) && response.contains(LName[j].toUpperCase()));
                } else if (paxtype[j].equalsIgnoreCase("Child")) {
                    //-SWAN/KAM*-CHD06
                    FName[j] = faker.name().firstName().replaceAll("[^a-zA-Z0-9]", "");
                    LName[j] = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "");
                    DOB[j] = gl.generateDateOfBirth("CHD");
                    mPaxName.put(FName[j].toUpperCase(), "Child");
                    String command = "-" + FName[j] + "/" + LName[j] + "*-CHD06";
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.click();
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.sendKeys(command);
                    isharesPageObjects1.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    Assert.assertTrue(response.contains(FName[j].toUpperCase()) && response.contains(LName[j].toUpperCase()));
                } else if (paxtype[j].equalsIgnoreCase("MultiSurnameIns")) {
                    //-GAYLE/SWAM*-INS/10JAN21
                    FName[j] = fname;
                    LName[j] = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "");
                    DOB[j] = gl.generateDateOfBirth("INS");
                    mPaxName.put(FName[j].toUpperCase(), "Ins");
                    String dob = gl.generateDateOfBirthNew("Ins");
                    System.out.println(dob);
                    String command = "-" + FName[j] + "/" + LName[j] + "*-INS/" + dob;
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.click();
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.sendKeys(command);
                    isharesPageObjects1.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    Assert.assertTrue(response.contains(FName[j].toUpperCase()) && response.contains(LName[j].toUpperCase()));
                }else if (paxtype[j].equalsIgnoreCase("Ins")) {
                    //-GAYLE/SWAM*-INS/10JAN21
                    FName[j] = faker.name().firstName().replaceAll("[^a-zA-Z0-9]", "");
                    LName[j] = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "");
                    DOB[j] = gl.generateDateOfBirth("INS");
                    mPaxName.put(FName[j].toUpperCase(), "Ins");
                    String dob = gl.generateDateOfBirthNew("Ins");
                    System.out.println(dob);
                    String command = "-" + FName[j] + "/" + LName[j] + "*-INS/" + dob;
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.click();
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.sendKeys(command);
                    isharesPageObjects1.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    Assert.assertTrue(response.contains(FName[j].toUpperCase()) && response.contains(LName[j].toUpperCase()));
                } else if (paxtype[j].equalsIgnoreCase("FQTV")) {

                    mPaxName.put(FName[j].toUpperCase(), "Adult");

                } else if (paxtype[j].equalsIgnoreCase("Inf"))//Adult+INF
                {
                    //-JEORGE/BROWN*-INFPUPPY/21JAN21
                    //Storing adult pax details
                    FName[j] = faker.name().firstName().replaceAll("[^a-zA-Z0-9]", "");
                    String firstname = FName[j];
                    LName[j] = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "");
                    String lastname = LName[j];
                    DOB[j] = gl.generateDateOfBirth("ADT");
                    mPaxName.put(FName[j].toUpperCase(), "Inf");
                    //Storing adult Inf details
                    infFName.add(firstname);
                    infLName.add(faker.name().lastName());
                    infDOB.add(gl.generateDateOfBirth("Inf"));
                    String dob = gl.generateDateOfBirthNew("Inf");
                    String command = "-" + FName[j] + "/" + lastname + "*-INF" + infLName.get(0) + "/" + dob;
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.click();
                    isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.sendKeys(command);
                    isharesPageObjects1.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    Assert.assertTrue(response.contains(FName[j].toUpperCase()) && response.contains(LName[j].toUpperCase()));
                }

                System.out.println("List of passenger names: " + FName);
            }

            if(misFQTV.get(getDriverID())==Boolean.TRUE)
            {
                FName=mergeArrays(mFF_FirstNames.get(getDriverID()),FName);
                LName=mergeArrays(mFF_LastNames.get(getDriverID()),LName);
                mPaxName.putAll(mFF_PaxType.get(getDriverID()));

            }

            logInfo.pass("I am entering pax details");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
        mFName.put(getDriverID(), FName);
        mLName.put(getDriverID(), LName);
        mDOB.put(getDriverID(), DOB);
        mInfFName.put(getDriverID(), infFName);
        mInfLName.put(getDriverID(), infLName);
        mInfDOB.put(getDriverID(), infDOB);
        mPaxName_PaxType.put(getDriverID(),mPaxName);
        mPaxNameList.put(getDriverID(), PaxNameList);

    }


