    public void checkinPaxWithSameName(ExtentTest logInfo,String originCity,String totalPax){
        try{

            String sharesResponse = null;

            gl.copyCmdToClipboardAndPaste(addCheckinCmd(originCity, 0), isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);
            isharesPageObjects1.SEND_ISHARES.click();
            gl.waitForProfileLoad();
            sharesResponse = isharesPageObjects1.SHARES_RESPONSE.getText();
            System.out.println(sharesResponse);

            if (sharesResponse.contains("NOT OPEN")) {
                openFlight(logInfo, mFlightNumber.get(getDriverID()), getSharesDate(), originCity);
                gl.ignoreTRNS(logInfo);

                gl.copyCmdToClipboardAndPaste(addCheckinCmd(originCity, 0), isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);
                isharesPageObjects1.SEND_ISHARES.click();
                sharesResponse = isharesPageObjects1.SHARES_RESPONSE.getText();
                System.out.println(sharesResponse);
            }

            for(int i=1;i<=2;i++)
            {
                String id = null;
                boolean Checkedin = false;
                String OrderId = (i==1)?mPNRNo1.get(getDriverID()):mOrderNumber.get(getDriverID());

                while (true) {

                    sharesResponse = isharesPageObjects1.SHARES_RESPONSE.getText();
                    System.out.println(sharesResponse);

                    if(sharesResponse.contains(OrderId))
                    {
                        String[] responseArr = sharesResponse.split("\n");
                        for (String response : responseArr)
                        {
                            if (response.contains(OrderId)) {
                                String[] responseLineArr = response.split(" ");
                                id = responseLineArr[1];
                                String command = "6:LK-"+id;
                                isharesPageObjects1.INPUT_TEXT_AREA_ROWS24.click();
                                isharesPageObjects1.INPUT_TEXT_AREA_ROWS24.sendKeys(command);
                                isharesPageObjects1.SEND_ISHARES.click();
                                sharesCheckinWithSameName(logInfo,totalPax,originCity);
                                Checkedin = true;
                                break;  //Breaks the for loop if PNR is found
                            } //end of if block
                        }   //End of for loop
                    }
                    else{
                        isharesPageObjects1.INPUT_TEXT_AREA_ROWS24.click();
                        isharesPageObjects1.INPUT_TEXT_AREA_ROWS24.sendKeys("MD");
                        isharesPageObjects1.SEND_ISHARES.click();
                        if(isharesPageObjects1.SHARES_RESPONSE.getText().contains("NO MORE")){
                            break;
                        }
                    }//End of if else block

                    if(Checkedin==true)
                    {
                        gl.copyCmdToClipboardAndPaste(addCheckinCmd(originCity, 0), isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);
                        isharesPageObjects1.SEND_ISHARES.click();
                        gl.waitForProfileLoad();
                        sharesResponse = isharesPageObjects1.SHARES_RESPONSE.getText();
                        System.out.println(sharesResponse);
                        break;  //Breaks the while loop if check in is done
                    }
                }
            }

        }
        catch(AssertionError | Exception e){
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

