    public boolean validateDeleteAPIS(String ADCInfo, ExtentTest logInfo) throws IOException {

        isharesPageObjects1.INPUT_TEXT_AREA_ROWS24.click();
        isharesPageObjects1.INPUT_TEXT_AREA_ROWS24.sendKeys(Keys.chord(Keys.CONTROL + "a" + Keys.BACK_SPACE));

        gl.copyCmdToClipboardAndPaste(ADCInfo, isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);
        isharesPageObjects1.SEND_ISHARES.click();

        gl.waitForProfileLoad();

        String response = isharesPageObjects1.SHARES_RESPONSE.getText();

        if (response.contains("APIS DELETED")) {
            gl.scrollPageDown();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            Assert.assertTrue(true);
            return true;

        } else {
            gl.scrollPageDown();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            Assert.assertTrue(false);
            return false;
        }

    }


    public String acceptAPISDeletion(String BaseCommand){

        String response = isharesPageObjects1.SHARES_RESPONSE.getText();
        isharesPageObjects1.INPUT_TEXT_AREA_ROWS24.sendKeys(Keys.chord(Keys.CONTROL + "a" + Keys.BACK_SPACE));

        String[] S = response.split("\n");

        String deleteCommand = "";

        for(int i=1;i<S.length-2;i++){
            deleteCommand = deleteCommand + S[i].replace(">","") + "\n" ;
            System.out.println("delete " + deleteCommand);
        }

//        System.out.println("Delete Coammand" + response);
//        String deleteAccept = response.replace("|","") + "260724                                  * EXPIRATION DATE\n" +
//                "CONFIRM DELETE:Y" ;
        System.out.println("Delete Coammand" + response);
        String deleteAccept = deleteCommand + "CONFIRM DELETE:Y" ;

        String ADCinfo =  deleteAccept;
        System.out.println("ADCinfo \n" + ADCinfo);
        return ADCinfo;

    }

