    public void searchavailabilityNativeShares(ExtentTest logInfo,String Origin,String Destination, String DepartureDate,String NoofPax,String ClassOfService,String Airline) {

        String command = null;
        try {

            //A PTYLAX 10NOV-CM
            String Date = DepartureDate.substring(0,2);
            int departdate = Integer.parseInt(Date);
            int flag =0;

            for(int i=departdate;i<=3;i++) {  // loop for date

                String DateFormatted = gl.plusDaysFromTodayNew(i);
                LocalDateTime departuredate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
                String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departuredate.toLocalDate());

                mSharesStartDateSegOne.put(getDriverID(), i); //storing this value to check Other segment date should be greater than this date
                System.out.println(DateFormatted +"Date in map");
                mFlightDepartDate.put(getDriverID(),DateFormatted);

                if(Airline.equalsIgnoreCase("CM")) {
                    command = "A " + Origin + Destination + " " + departureDateFormatted + "-" + "CM";
                }
                else if (Airline.equalsIgnoreCase("DL")) {
                    command = "A " + Origin + Destination + " " + departureDateFormatted + "-" + "DL";
                }

                System.out.println("command " +command);
                sendCmdToNativeSharesValidateResponse(command);

                String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                gl.checkForErrors(command,Response,logInfo);

                isharesPageObjects1.NATIVE_SHARES_CLEAR_ALL.click();

                for(int j=1;j<=3;j++) {  //loop for flight

                    String command2 = "N" + NoofPax + ClassOfService + j; //N2Y1

                    sendCmdToNativeSharesValidateResponse(command2);
                    gl.checkForErrors(command2,isharesPageObjects1.NATIVE_SHARES_RESPONSE_VALIDATE_LINE2.getText(),logInfo);
                    System.out.println(command2);

                    if(isharesPageObjects1.NATIVE_SHARES_RESPONSE_VALIDATE_LINE2.getText().contains("NO MORE FOR DISPLAY")){

                        isharesPageObjects1.NATIVE_SHARES_CLEAR_ALL.click();
                        sendCmdToNativeSharesValidateResponse(command);

                        System.out.println(command);


                    } else{

                        String response = isharesPageObjects1.NATIVE_SHARES_ETKT_RESPONSE_VALIDATE.getText();
                        mFlightNumber.put(getDriverID(),response.substring(7,10));
                        System.out.println("FFlight number "+response.substring(7,10));

                        flag=1;
                        break;

                    }

                }

                if(flag==1){
                    isharesPageObjects1.NATIVE_SHARES_CLEAR_ALL.click();
                    break;
                }
            }

            logInfo.pass("Search for availability");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

