    public void enterPassengerDetailsNRPS(ExtentTest logInfo, String[] paxtype, String[] paxCode) {

        int totalpaxCount = paxtype.length;

        Faker faker = new Faker(new Locale("en-US"));
        FName = new String[totalpaxCount];
        mFName.put(getDriverID(), FName);
        PassengerName = new String[totalpaxCount];
        PassengerLastName = new String[totalpaxCount];
        DOB = new String[totalpaxCount];
        mDOB.put(getDriverID(), DOB);
        LName = new String[totalpaxCount];
        mLName.put(getDriverID(), LName);
        mPaxType.put(getDriverID(), paxtype);
        isNonRevenue.put(getDriverID(),false);
        HashMap<String,String> accCode = new HashMap<>();
        ArrayList<String> PaxNameList = new ArrayList<>();

        String command = null;

        try {

            for (int j = 0; j < totalpaxCount; j++) {

                if (paxtype[j].equalsIgnoreCase("NRPS") || paxtype[j].equalsIgnoreCase("NRSA")) {

                    isNonRevenue.put(getDriverID(),true);
                    FName[j] = faker.name().firstName().replaceAll("[^a-zA-Z0-9]", "");
                    LName[j] = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "");
                    DOB[j] = gl.generateDateOfBirth("ADT");
                    mPaxName.put(FName[j].toUpperCase(), paxtype[j]);

                    if(totalpaxCount>1) {
                        if (j < totalpaxCount - 1) {
                            command = "-" + paxCode[0] + "03/" + FName[j] + "/" + LName[j];
                            accCode.put((FName[j] + ", " + LName[j]).toUpperCase(),paxCode[0]);
                            System.out.println(paxtype[j] + "First pax : " + (FName[j] + ", " + LName[j]));
                        } else {
                            command = "-" + paxCode[1] + "03/" + FName[j] + "/" + LName[j];
                            accCode.put( (FName[j] + ", " + LName[j]).toUpperCase(),paxCode[1]);
                            System.out.println(paxtype[j] + "Second pax : " + (FName[j] + ", " + LName[j]));
                        }

                    }else{
                        command = "-" + paxCode[j] + "03/" + FName[j] + "/" + LName[j];
                        accCode.put((FName[j] + ", " + LName[j]).toUpperCase(),paxCode[j]);
                        System.out.println(paxtype[j] + "First pax : " + (FName[j] + ", " + LName[j]));
                    }

                    gl.sendCmdValidateResponse(command,FName[j].toUpperCase(),LName[j].toUpperCase(),logInfo);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                }
            }

            logInfo.pass("I am entering pax details");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }

        mFName.put(getDriverID(), FName);
        mLName.put(getDriverID(), LName);
        mDOB.put(getDriverID(), DOB);
        NonRevenuePaxCode.put(getDriverID(),accCode);
        mPaxName_PaxType.put(getDriverID(),mPaxName);
        mPaxNameList.put(getDriverID(), PaxNameList);

        System.out.println(" Total List :" + NonRevenuePaxCode.get(getDriverID()));

    }

