    public void readFlightData(String TotalRowCount) throws IOException {

        FileInputStream inputStream = new FileInputStream(new File(".\\src\\test\\ExcelData\\FlightData.xlsx"));
        XSSFWorkbook workbook = new XSSFWorkbook(inputStream);
        XSSFSheet sheet = workbook.getSheet("FlightsData1");
        int totalFlights = sheet.getPhysicalNumberOfRows();
        System.out.println("Total row count " +totalFlights);

        List<String> flightnum = new ArrayList<>();
        List<String> DptDate = new ArrayList<>();
        List<String> DptCity = new ArrayList<>();

        for(int i=1;i<totalFlights;i++){

            String fltNum = sheet.getRow(i).getCell(0).toString();
            flightnum.add(fltNum);
            String flightDate = sheet.getRow(i).getCell(1).toString();
            DptDate.add(flightDate);
            String originCity = sheet.getRow(i).getCell(2).toString();
            DptCity.add(originCity);
        }

        flightNumber.put(getDriverID(),flightnum);
        flightDate.put(getDriverID(),DptDate);
        OriginCity.put(getDriverID(),DptCity);

        workbook.close();
        inputStream.close();

    }


    public void readFlightData2(String TotalRowCount) throws IOException {

        FileInputStream inputStream = new FileInputStream(new File(".\\src\\test\\ExcelData\\FlightData.xlsx"));
        XSSFWorkbook workbook = new XSSFWorkbook(inputStream);
        XSSFSheet sheet = workbook.getSheet("FlightsData2");

        List<String> flightnum = new ArrayList<>();
        List<String> DptDate = new ArrayList<>();
        List<String> DptCity = new ArrayList<>();

        int totalFlights = Integer.parseInt(TotalRowCount);

        for(int i=1;i<totalFlights;i++){

            String fltNum = sheet.getRow(i).getCell(0).toString();
            flightnum.add(fltNum);
            String flightDate = sheet.getRow(i).getCell(1).toString();
            DptDate.add(flightDate);
            String originCity = sheet.getRow(i).getCell(2).toString();
            DptCity.add(originCity);
        }

        flightNumber.put(getDriverID(),flightnum);
        flightDate.put(getDriverID(),DptDate);
        OriginCity.put(getDriverID(),DptCity);

        workbook.close();
        inputStream.close();

    }

