    public void removeFlightFromIndexList(ExtentTest logInfo,String FlightNo){

        try {

            //KEDLT360ALL
            gl.sendCmdValidateResponse("KE*WKG",logInfo);
            gl.waitForProfileLoad();
            logInfo.pass("Remove flight from working reaccommodation index list");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            String response = isharesPageObjects1.SHARES_RESPONSE.getText();

            if(!response.contains("NO FLIGHTS PRESENT")){

                String RemoveFlight = "KEDLT" + FlightNo + "ALL";
                gl.sendCmdValidateResponse(RemoveFlight,"ALL PROCESSED","INVLD FLT NBR",logInfo);
                gl.waitForProfileLoad();
                logInfo.pass("Remove flight from working reaccommodation index list");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                logInfo.pass("Remove flight from working reaccommodation index list");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            }

            gl.sendCmdValidateResponse("KAI",logInfo);
            String response1 = isharesPageObjects1.SHARES_RESPONSE.getText();

            if(response1.contains("INVENTORY READY TO PROCESS-RTP LIST")){

                String RemoveFlight = "KAI" + FlightNo;
                gl.sendCmdValidateResponse(RemoveFlight,logInfo);
                gl.waitForProfileLoad();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                String KAIresponse = isharesPageObjects1.SHARES_RESPONSE.getText();
                String[] RTPList = KAIresponse.split("\n");

                if(!KAIresponse.contains("RTP INACTIVE FLT")){
                    String[] RTPValue = RTPList[3].split(" ");

                    System.out.println("RTP List" + RTPList[3]);
                    System.out.println("RTP Value" +RTPValue[0]);
                    String removeFlightFromRTP = "KSM" + FlightNo + "*" + RTPValue[2];
                    gl.sendCmdValidateResponse(removeFlightFromRTP,logInfo);
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    //Checking Response
                    String removeFlightFromRTPResponse = isharesPageObjects1.SHARES_RESPONSE.getText();
                    if(removeFlightFromRTPResponse.contains("FIN OR CLEAR"))
                    {
                        gl.sendCmdValidateResponse("KSC",logInfo);

                        gl.sendCmdValidateResponse("KAI",logInfo);
                        response1 = isharesPageObjects1.SHARES_RESPONSE.getText();

                        if (response1.contains("INVENTORY READY TO PROCESS-RTP LIST")) {

                            RemoveFlight = "KAI" + FlightNo;
                            gl.sendCmdValidateResponse(RemoveFlight, "INVENTORY READY TO PROCESS-RTP LIST",logInfo);
                            gl.waitForProfileLoad();
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                            KAIresponse = isharesPageObjects1.SHARES_RESPONSE.getText();
                            RTPList = KAIresponse.split("\n");

                            if (!KAIresponse.contains("RTP INACTIVE FLT")) {
                                RTPValue = RTPList[3].split(" ");

                                System.out.println("RTP List" + RTPList[3]);
                                System.out.println("RTP Value" + RTPValue[2]);
                                removeFlightFromRTP = "KSM" + FlightNo + "*" + RTPValue[2];
                                gl.sendCmdValidateResponse(removeFlightFromRTP, "RTP-CANCEL", "RTP-MODIFY",logInfo);
                                gl.waitForProfileLoad();
                                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                            }
                        }

                    }

                    String ConfirmremoveFlightFromRTP = "KSREMOVE";
                    gl.sendCmdValidateResponse(ConfirmremoveFlightFromRTP,"REMOVED FROM RTP LIST",logInfo);
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                }


            }

            gl.waitForProfileLoad();




        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }

    }

    public boolean selectFLightFrequency(ExtentTest logInfo,LocalDate BookFlight,String FrequencyRange){
        boolean DayMatch = false;
        try {
            String Day = null;
            HashMap<Integer, String> DayIndex = new HashMap<>();
            DayIndex.put(0,"Sunday");
            DayIndex.put(1,"Monday");
            DayIndex.put(2,"Tuesday");
            DayIndex.put(3,"Wednesday");
            DayIndex.put(4,"Thursday");
            DayIndex.put(5,"Friday");
            DayIndex.put(6,"Saturday");

            DayOfWeek dayOfWeek = BookFlight.getDayOfWeek();

            for (int j = 21; j < FrequencyRange.length(); j++)
            {
                System.out.println(FrequencyRange);
                System.out.println("Index output" + FrequencyRange.charAt(j));
                char ch = FrequencyRange.charAt(j);
                if (j >= 22 && j <= 28 && ch!=' ')
                {
                    System.out.println("The day is " + DayIndex.get(j - 22));
                    Day = DayIndex.get(j - 22);
                    break;
                }
            }

            if(dayOfWeek.toString().equalsIgnoreCase(Day))
            {
                DayMatch = true;
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }

        return DayMatch;
    }

