    public void changeSegmentsToCMUSEDForAllPax(ExtentTest logInfo,String statusType, String noOfPax, String noOfSegments) throws IOException {

        int totalPax = Integer.parseInt(noOfPax);
        int totalSegments = Integer.parseInt(noOfSegments);
        gl.sendCmdValidateResponse("*" + mOrderNumber.get(getDriverID()),logInfo);

        if(statusType.equalsIgnoreCase("CM USED")) {
            for (int i = 1; i <= totalPax; i++) {

                for (int j = 1; j <= totalSegments; j++) {

                    gl.sendCmdValidateResponse("T-ET/STATUS/USED/" + (i) + "." + (j) + "*", "-OK-",logInfo);
                    logInfo.pass("I change the segments to CM USED");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }
            }
        }else if(statusType.equalsIgnoreCase("Remove CM USED")) {
            for (int i = 0; i < totalPax; i++) {

                for (int j = 0; j < totalSegments; j++) {

                    gl.sendCmdValidateResponse("T-ETREMOVE/U" + (i + 1) + "." + (j + 1) , "-OK-",logInfo);
                    logInfo.pass("I change the segments to CM USED");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }
            }
        }else if(statusType.equalsIgnoreCase("REVOKE")) {
            for (int i = 1; i <= totalPax; i++) {

                for (int j = 1; j <= totalSegments; j++) {

                    gl.logCommand(logInfo,"T-ETREVOKE" + (i) + "." + (j));
                    gl.sendCmdValidateResponse("T-ETREVOKE" + (i) + "." + (j), "-OK-",logInfo);
                    logInfo.pass("I change the segments to REVOKE");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }
            }

        }else if(statusType.equalsIgnoreCase("Remove REVOKE")) {
            for (int i = 0; i < totalPax; i++) {

                for (int j = 0; j < totalSegments; j++) {

                    gl.sendCmdValidateResponse("T-ETREMOVE/R" + (i + 1) + "." + (j + 1) , "-OK-",logInfo);
                    logInfo.pass("I change the segments to CM USED");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }
            }
        }else if(statusType.equalsIgnoreCase("VOID")) {

            gl.sendCmdValidateResponse("T-ETVOID", "-OK-",logInfo);
            logInfo.pass("I change the segments to VOID");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");


        }else if(statusType.equalsIgnoreCase("Remove VOID")) {
            for (int i = 0; i < totalPax; i++) {

                for (int j = 0; j < totalSegments; j++) {

                    gl.sendCmdValidateResponse("T-ETREMOVE/V" + (i + 1) + "." + (j + 1) , "-OK-",logInfo);
                    logInfo.pass("I change the segments to VOID");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }
            }
        }else if(statusType.equalsIgnoreCase("ParticularSegVOID")) {
            for (int j = 1; j <=14; j=j+2) {
                gl.sendCmdValidateResponse("T-ETVOID" + j, "-OK-","INVALID - NOT PRIME ETKT   ",logInfo);
                logInfo.pass("I change the segments to VOID for seg " + j);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

        }else if(statusType.equalsIgnoreCase("VoidAfterCheckIN")) {
            for (int i = 0; i < totalPax; i++) {
                gl.logCommand(logInfo,"T-ETVOID" + i);
                gl.sendCmdValidateResponse("T-ETVOID" + i, "INVALID ETKT ITEM NUMBER",logInfo);
                logInfo.pass("I check segment status after check in");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

        }else if(statusType.equalsIgnoreCase("Detach")) {
            for (int i = 0; i < totalPax; i++) {
                gl.logCommand(logInfo,"T-ETDETACH" + (i+1));
                gl.sendCmdValidateResponse("T-ETDETACH" + (i+1), "-OK-",logInfo);
                logInfo.pass("I change the segments to Detach for seg");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

            gl.logCommand(logInfo,"*ET");
            gl.sendCmdValidateResponse("*ET", "INVALID - NO ETKT FOUND","INVALID ETKT ITEM NUMBER",logInfo);
            logInfo.pass("I verified the segments to Detach");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.logCommand(logInfo,"*EH");
            gl.sendCmdValidateResponse("*EH", "INVALID - NO ETKT FOUND","INVALID ETKT ITEM NUMBER",logInfo);
            logInfo.pass("I verified the segments history");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        }else if(statusType.equalsIgnoreCase("Lifted")) {
            for (int i = 1; i <= totalPax; i++) {

                for (int j = 1; j <= totalSegments; j++) {
                    //T-ET/STATUS/LIFTED/1.1*
                    gl.logCommand(logInfo,"T-ET/STATUS/LIFTED/" + (i) + "." + (j) + "*");
                    gl.sendCmdValidateResponse("T-ET/STATUS/LIFTED/" + (i) + "." + (j)+ "*", "-OK-",logInfo);
                    logInfo.pass("I change the segments to Lifted");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }
            }

        }


    }

