    public void performASA(ExtentTest logInfo, String totalSegments,String AssignType) {
        try {

            int TotalSeg = Integer.parseInt(totalSegments);
            String Response;

            if (AssignType.equalsIgnoreCase("true")) {
                gl.logCommand(logInfo, "6:A");
                gl.sendCmdValidateResponse("6:A", "SEATS ASSIGNED",logInfo);
                Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                Assert.assertFalse(Response.contains("UNASSIGNED"));
                logInfo.pass("I perform ASA to all the passengers and validated seat assigned");

            } else if (AssignType.equalsIgnoreCase("SpecificSegment")) {
                gl.logCommand(logInfo, "6:A" + totalSegments);
                gl.sendCmdValidateResponse("6:A" + totalSegments, "SEATS ASSIGNED",logInfo);
                Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                Assert.assertFalse(Response.contains("UNASSIGNED"));
                logInfo.pass("I perform Specific Segment ASA to all the passengers and validated seat assigned");

            } else if (AssignType.equalsIgnoreCase("WindowSeat")) {
                gl.logCommand(logInfo, "6:A|W");
                gl.sendCmdValidateResponse("6:A|W", "SEATS ASSIGNED",logInfo);
                Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                Assert.assertFalse(Response.contains("UNASSIGNED"));
                logInfo.pass("I perform Window Seat ASA to all the passengers and validated seat assigned");

            } else if (AssignType.equalsIgnoreCase("ExitSeat")) {
                gl.logCommand(logInfo, "6:A|E");
                gl.sendCmdValidateResponse("6:A|E", "SEATS ASSIGNED", "ADVISE CUSTOMER EXIT SEATS ASSIGNED",logInfo);
                Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                Assert.assertFalse(Response.contains("UNASSIGNED"));
                logInfo.pass("I perform Exit Seat ASA to all the passengers and validated seat assigned");

            } else if (AssignType.equalsIgnoreCase("InvalidSegment")) {
                gl.logCommand(logInfo, "6:A" + totalSegments);
                gl.sendCmdValidateResponse("6:A" + totalSegments, "INVLD SEG NBR ",logInfo);
                logInfo.pass("I perform Invalid Segment ASA to all the passengers and validated seat assigned");

            } else if (AssignType.equalsIgnoreCase("InvalidPaxCount")) {
                gl.logCommand(logInfo, "6:A|N" + totalSegments);
                gl.sendCmdValidateResponse("6:A|N" + totalSegments, "INVALID DELIMITER",logInfo);
                logInfo.pass("I perform Invalid Pax ASA to all the passengers and validated seat assigned");

            } else if (AssignType.equalsIgnoreCase("AssignAndDivide")) {
                gl.logCommand(logInfo, "D" + totalSegments);
                System.out.println("pax name " + mFName.get(getDriverID())[0]);
                gl.sendCmdValidateResponse("D" + totalSegments, mFName.get(getDriverID())[0], "FARE QUOTE-AUTO PRICED ",logInfo);
                logInfo.pass("I divide the pnr");

            } else if (AssignType.equalsIgnoreCase("VSeat")) {
                gl.logCommand(logInfo, "6:A|V");
                gl.sendCmdValidateResponse("6:A|V", "SEATS ASSIGNED",logInfo);
                Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                Assert.assertFalse(Response.contains("UNASSIGNED"));
                logInfo.pass("I perform V Seat ASA to all the passengers and validated seat assigned");

            } else if (AssignType.equalsIgnoreCase("WaitList")) {

                String Seatcmd = "";

                for (int j = 0; j < totalPax; j++)
                {
                    gl.ignoreTRNS(logInfo);

                    Seatcmd = "6:ZT" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                            + mOriginCity.get(getDriverID()) + "-" + mFName.get(getDriverID())[j] + "/" + mLName.get(getDriverID())[j]
                            + "\n" + assignEconomySeatNumber(logInfo,"REGULAR",j);

                    isharesPageObjects1.FORMSIZE_DROPDOWN.click();
                    isharesPageObjects1.FORMSIZE_SELECT24.click();

                    gl.logCommand(logInfo, Seatcmd);
                    gl.copyCmdToClipboardAndPaste(Seatcmd, isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);

                    isharesPageObjects1.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    Assert.assertTrue(Response.contains("002-OK-"));
                    logInfo.pass("I assign seat");
                }


                isharesPageObjects1.FORMSIZE_DROPDOWN.click();
                isharesPageObjects1.FORMSIZE_SELECT1.click();


            }
            else
            {

                for (int i = 1; i <= TotalSeg; i++)
                {

                    gl.logCommand(logInfo, "6:A" + i);
                    gl.sendCmdValidateResponse("6:A" + i, "SEATS ASSIGNED",logInfo);
                    Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    Assert.assertTrue(!Response.contains("UNASSIGNED"));
                    logInfo.pass("I perform ASA to all the passengers and validated seat assigned");

                    gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", mOrderNumber.get(getDriverID()),logInfo);
                    logInfo.pass("I perform ASA to all the passengers and validated seat assigned");

                    gl.sendCmdIfRequired("ER", mOrderNumber.get(getDriverID()),logInfo);
                    logInfo.pass("I perform ASA to all the passengers and validated seat assigned");
                }

                gl.sendCmdValidateResponse("*S/ALL", "SEATS ASSIGNED",logInfo);
                logInfo.pass("I perform ASA to all the passengers and validated seat assigned");

            }

            if (AssignType.equalsIgnoreCase("true") || AssignType.equalsIgnoreCase("SpecificSegment")
                    || AssignType.equalsIgnoreCase("WindowSeat") || AssignType.equalsIgnoreCase("ExitSeat")
                    || AssignType.equalsIgnoreCase("InvalidSegment"))
            {
                gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *", mOrderNumber.get(getDriverID()),logInfo);
                logInfo.pass("I perform ASA to all the passengers and validated seat assigned");

                gl.sendCmdIfRequired("ER", mOrderNumber.get(getDriverID()),logInfo);
                logInfo.pass("I perform ASA to all the passengers and validated seat assigned");
            }

        } catch(AssertionError | Exception e){

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

    public String returnSeatNumber(String economySeatMap,String typeOfSeat)
    {
        String[] economySeatMapLines=economySeatMap.split("\n");
        char number = '0';
        char[] temp=economySeatMapLines[0].toCharArray();

        for(int i=0;i<temp.length;i++)
        {
            char ch = temp[i];
            if(ch==' ')
            {
                temp[i]=number;
            }
            else if(ch!='Y')
            {
                number=temp[i];
            }
        }

        economySeatMapLines[0]=new String(temp);

        String seatDigits1=economySeatMapLines[0];
        String seatDigits2=economySeatMapLines[1];

        int index=-1;
        int seatRow=-1;
        for(int i=2;i<economySeatMapLines.length-1;i++)
        {
            if(economySeatMapLines[i].contains(typeOfSeat) && economySeatMapLines[i].indexOf(typeOfSeat)!=0)
            {
                index=economySeatMapLines[i].indexOf(typeOfSeat);
                seatRow=i;
                break;
            }
        }

        if(index==-1)
            return null;
        else
            return String.valueOf(seatDigits1.charAt(index))+String.valueOf(seatDigits2.charAt(index))
                    +String.valueOf(economySeatMapLines[seatRow].charAt(0)) ;

    }

    public String returnEconomySeatMap(String rawSeatMap)
    {
        String economySeatMap="";
        // Split the seat map into lines
        String[] seatMapLines = rawSeatMap.split("\n");

        // Find the first occurrence of 'Y'
        int startRow = -1;
        int startColumn = -1;
        int stopColumn =-1;

        for (int i = 0; i < seatMapLines.length; i++)
        {
            String line = seatMapLines[i];

            if(line.contains(mFlightNumber.get(getDriverID())))
            {
                startColumn = line.indexOf('Y');
                startRow = i;
                for(int j=startColumn+3;j<seatMapLines[i+1].toCharArray().length;j++)
                {
                    if(seatMapLines[i+1].toCharArray()[j]==' ')
                    {
                        stopColumn=j;
                        break;
                    }
                }

                break; // Stop when the first 'Y' is found
            }
        }

        // If 'Y' is found, extract the horizontal and vertical portions
        if (startRow != -1 && startColumn != -1)
        {

            // Extract vertically from the row where 'Y' was found
            for (int i = startRow; i < seatMapLines.length; i++)
            {
                String line = seatMapLines[i];

                if(line.contains(".-TAKEN"))
                    break;
                else if (line.length() > startColumn && line.length()>=stopColumn)    // Only print the portion of the string starting from 'Y' in each row
                    economySeatMap=economySeatMap+line.substring(startColumn,stopColumn)+"\n";

            }
        }
        return economySeatMap;
    }

    public String assignEconomySeatNumber(ExtentTest logInfo,String typeOfSeat,int paxIndex)
    {
        String seatNumber=null;
        try {

            HashMap<String, String> seatMapLegend = new HashMap<String, String>()
            {
                {
                    put("AVAIL", "@");
                    put("TAKEN", ".");
                    put("BLKD", "B");
                    put("UNUSABLE", "U");
                    put("SMOKE", "S");
                    put("NOSMOKE", "N");
                    put("INDIF", "I");
                    put("EXIT", "E");
                    put("WING", "W");
                    put("ADVANCED", "A");
                    put("HELD", "H");
                    put("PERMBLKD", "P");
                    put("PREMIUM", "V");
                    put("BULKHEAD", "Q");
                    put("INFANT/TAKEN", "F");
                    put("INFANT/SEATED", "$");
                    put("REGULAR", "T");
                    put("PREMIUM WINDOW", "J");
                    put("PREMIUM AISLE", "Z");
                    put("OA SEAT", "X");
                }
            };

            isharesPageObjects1.FORMSIZE_DROPDOWN.click();
            isharesPageObjects1.FORMSIZE_SELECT1.click();

            //            6:*302/18JANPTY.Y ---> To show SEAT MAP

            String command = "6:*" + mFlightNumber.get(getDriverID()) + "/" + gl.sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID())) + mOriginCity.get(getDriverID()) + "." +"Y";

            gl.logCommand(logInfo,command);
            gl.sendCmdValidateResponse(command, mOriginCity.get(getDriverID()).toUpperCase() + "-" + mDestinationcity.get(getDriverID()).toUpperCase(), "@-AVAIL  .-TAKEN", logInfo);

            String rawSeatMap = isharesPageObjects1.SHARES_RESPONSE.getText();

            if(rawSeatMap.contains("TAKEN"))
            {
                seatNumber=returnSeatNumber(returnEconomySeatMap(rawSeatMap),seatMapLegend.get(typeOfSeat));
            }
            else
            {
                logInfo.info(MarkupHelper.createLabel("SEAT MAP NOT DISPLAYED", ExtentColor.PURPLE));
            }

            gl.ignoreTRNS(logInfo);

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            org.testng.Assert.fail("This step failed.. so stopping...");
        }

        if(seatNumber!=null)
        {
            logInfo.pass("I assign Seat "+seatNumber+" to : "+ mFName.get(getDriverID())[paxIndex]);
            return seatNumber;
        }
        else
        {
            logInfo.info(MarkupHelper.createLabel("NO SEATS AVAILABLE FOR REQUIRED TYPE. HENCE SEATS UNASSIGNED", ExtentColor.PURPLE));
            return "";
        }

    }


