                    infFName.add(firstname);
                    infLName.add(faker.name().lastName().replaceAll("[^a-zA-Z0-9]", ""));
                    infDOB.add(gl.generateDateOfBirth("Inf"));
//                    mPaxName.put(infLName.get(0).toUpperCase(), "Inf");

