    public void dividePnr(ExtentTest logInfo,String TotalPaxToDivide) {
        try {

            DividePNR:  for(int i = 0; ; i++)
            {
                String command = "D" + TotalPaxToDivide;
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command,logInfo);
                logInfo.pass("I divide the pnr");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                gl.logCommand(logInfo, "6P");
                gl.sendCmdValidateResponse("6P", "6P *",logInfo);
                logInfo.pass("I save the divided pnr");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                gl.logCommand(logInfo, "F");
                gl.sendCmdValidateResponse("F", "RECORD FILED",logInfo);
                String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                mPNRNo1.put(getDriverID(), Response.substring(13, 19));  // Stored newly created PNR in map mPnr1
                logInfo.pass("I capture divided pnr");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                gl.logCommand(logInfo, "6P#ER");
                gl.sendCmdValidateResponse("6P#ER", "6P#ER *", mOrderNumber.get(getDriverID()),"CHANGES RESTRICTED - COMPLETE PNR DIVIDE AND ER",logInfo);
                gl.logCommand(logInfo, "ER");
                gl.sendCmdIfRequired("ER", mOrderNumber.get(getDriverID()), logInfo);
                logInfo.pass("I save and retrieve divided pnr");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                if(isharesPageObjects1.SHARES_RESPONSE.getText().contains("SIMULT CHGS TO PNR")){
                    gl.logCommand(logInfo,"IR");
                    gl.sendCmdValidateResponse("IR", mOrderNumber.get(getDriverID()),logInfo);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                    continue DividePNR;
                }
                else if(isharesPageObjects1.SHARES_RESPONSE.getText().contains("RCVD-P")) {
                    break;
                }
            }

            ignoreTRNS(logInfo);

            gl.logCommand(logInfo,"*" + mPNRNo1.get(getDriverID()));
            gl.sendCmdValidateResponse("*" + mPNRNo1.get(getDriverID()) ,mPNRNo1.get(getDriverID()),logInfo);
            logInfo.pass("I save and retrieve divided pnr");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

