    public void rebookSegment(ExtentTest logInfo,String SegmentNumber,String rebookType) {

        try {
            if(rebookType.equalsIgnoreCase("OverBookOldSeg")){
                String command = "." + SegmentNumber + "@" +
                        sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()) + 3) + "/SU";
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"OK",logInfo);
                logInfo.pass("I over book the segment");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if(rebookType.equalsIgnoreCase("RebookSeg")){
                mAltFlightNumber.put(getDriverID(),mFlightNumber.get(getDriverID()));
                mAltrFlightDays.put(getDriverID(),mSharesStartDateSegOne.get(getDriverID()));

                System.out.println("Old Flight number " +mAltFlightNumber.get(getDriverID()));
                System.out.println("Old Flight date " +mAltrFlightDays.get(getDriverID()));
                String command = "X" + SegmentNumber;
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"NEXT REPLACES",logInfo);
                logInfo.pass("I cancel the segment");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if(rebookType.equalsIgnoreCase("RebookConnectingSeg")){
                mAltFlightNumber.put(getDriverID(),mConnectingFlightNumber.get(getDriverID()));
                mAltrFlightDays.put(getDriverID(),mSharesStartDateSegTwo.get(getDriverID()));
                System.out.println("Old Flight number " +mAltFlightNumber.get(getDriverID()));
                System.out.println("Old Flight date " +mAltrFlightDays.get(getDriverID()));
                String command = "X" + SegmentNumber;
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"NEXT REPLACES",logInfo);
                logInfo.pass("I cancel the segment");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if(rebookType.equalsIgnoreCase("DeleteSegment")){

                String command = "X" + SegmentNumber;
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"NEXT REPLACES","SEGMENTS CANCELED",logInfo);
                logInfo.pass("I cancel the segment");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if (rebookType.equalsIgnoreCase("ChangeCOSForOneSegment")) {
//            .1@C
                gl.sendCmdValidateResponse("*" + mOrderNumber.get(getDriverID()),logInfo);
                String command = "." + SegmentNumber + "@C";
                gl.sendCmdValidateResponse(command, "OK",logInfo);
                gl.logCommand(logInfo, command);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                gl.logCommand(logInfo,saveAndRetrieve);
                gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER",mFlightNumber.get(getDriverID()),"WARNING - TRANSACT WILL UNSEAT CKD-IN PSGR",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                gl.logCommand(logInfo,saveAndRetrieve);
                gl.sendCmdIfRequired(endAndretrieve, mFlightNumber.get(getDriverID()),"WARNING - TRANSACT WILL UNSEAT CKD-IN PSGR",logInfo);
                gl.sendCmdIfRequired(endAndretrieve, mFlightNumber.get(getDriverID()),"WARNING - TRANSACT WILL UNSEAT CKD-IN PSGR",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if(rebookType.equalsIgnoreCase("RebookWithNewDate")){
//                .2@12JUL
                String command = "." + SegmentNumber + "@" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID())+ 1);
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"OK",logInfo);
                logInfo.pass("I rebook the segment with a new date");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                gl.logCommand(logInfo,saveAndRetrieve);
                gl.sendCmdValidateResponse(saveAndRetrieve,logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                gl.logCommand(logInfo,endAndretrieve);
                gl.sendCmdIfRequired(endAndretrieve, mOrderNumber.get(getDriverID()), sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID())),logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

    public void addRemarkToPnr(ExtentTest logInfo,String RemarkType) {

        try {
            if(RemarkType.equalsIgnoreCase("CDM"))
            {
                String command = "5CDM-UNABLE TO PROCESS 071095 1350";
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,command + " *",logInfo);
                logInfo.pass("I add remark to the pnr");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if(RemarkType.equalsIgnoreCase("Formatted"))
            {
                String command = "5.CHRG*GBP25.00*FREE TEXT";
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"5.CHRG*GBP25.00*FREE TEXT *",logInfo);
                logInfo.pass("I add remark to the pnr");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if(RemarkType.equalsIgnoreCase("ModifyFormatted"))
            {
                String command = "51@.UMNR*GBP25.00*FREETEXT";
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,command + " *",logInfo);
                logInfo.pass("I modify remark to the pnr");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if(RemarkType.equalsIgnoreCase("DeleteFormatted"))
            {
                String command = "51@";
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"NEXT REPLACES",logInfo);
                logInfo.pass("I delete remark to the pnr");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if(RemarkType.equalsIgnoreCase("OSI"))
            {
                String command = "3 OSI CM PSGR IS CAB INSPECTOR";
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,command+"*",logInfo);
                logInfo.pass("I add remark to the pnr");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if(RemarkType.equalsIgnoreCase("Ticketing"))
            {
                //                T-RAO0038765432098/LAX/20JAN23/12345678
                System.out.println(sharesFormatDateFromGUIWithYear(mSharesStartDateSegOne.get(getDriverID())));
                String command = "T-RAO0038765432098/" + mOriginCity.get(getDriverID()) + "/" + sharesFormatDateFromGUIWithYear(mSharesStartDateSegOne.get(getDriverID())) + "/12345678";
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"TICKETING  REMARKS",logInfo);
                logInfo.pass("I perform ticketing remark");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

            gl.sendCmdValidateResponse("6P#ER", "6P#ER *",mOrderNumber.get(getDriverID()),logInfo);
            gl.sendCmdIfRequired("ER", mOrderNumber.get(getDriverID()),logInfo);

            if(RemarkType.equalsIgnoreCase("DeleteFormatted")){
                if(!isharesPageObjects1.SHARES_RESPONSE.getText().contains("REMARKS ADDED")){
                    gl.sendCmdValidateResponse("MD",logInfo);
                    Assert.assertFalse(isharesPageObjects1.SHARES_RESPONSE.getText().contains("REMARKS ADDED"));
                }

            }
            else{
                if(!isharesPageObjects1.SHARES_RESPONSE.getText().contains("REMARKS ADDED")){
                    gl.sendCmdValidateResponse("MD",logInfo);
                }else if(!isharesPageObjects1.SHARES_RESPONSE.getText().contains("REMARKS ADDED")){
                    gl.sendCmdValidateResponse("MD","REMARKS ADDED",logInfo);
                }
            }

            logInfo.pass("I save remark to the pnr" + RemarkType);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }

    }

