    public void ModifyGroupZoneTable(ExtentTest logInfo,String ModifyType){

        try{
            String PrecId="";
            //       	PAG*/CABIN
            if(ModifyType.equalsIgnoreCase("AddItemGroupZoneTable"))
            {
                String ModifyGroupZoneTable = "PAG*/CABIN";
                gl.logCommand(logInfo,ModifyGroupZoneTable);
                gl.sendCmdValidateResponse(ModifyGroupZoneTable,"GROUP/ZONE TABLE",logInfo);
                logInfo.pass("I display cabin item in group zone table");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

//            PAGA1#CABIN#C#ED31OCT24#DD31DEC24#ZONE1
                ModifyGroupZoneTable = "PAGA1|CABIN|C|ED" + gl.plusDaysFromTodayNewCheckYear(01) + "|DD" + gl.plusDaysFromTodayNewCheckYear(10)
                        + "|ZONE1";
                gl.logCommand(logInfo,ModifyGroupZoneTable);
                gl.sendCmdValidateResponse(ModifyGroupZoneTable,"CABIN    C",logInfo);
                logInfo.pass("I add cabin item in group zone table");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                int StartIndexPrecId = isharesPageObjects1.SHARES_RESPONSE.getText().indexOf("CABIN    C");
                PrecId = isharesPageObjects1.SHARES_RESPONSE.getText().substring(StartIndexPrecId-5,StartIndexPrecId-1).trim();

                ModifyGroupZoneTable = "PAG*/CABIN";
                gl.logCommand(logInfo,ModifyGroupZoneTable);
                gl.sendCmdValidateResponse(ModifyGroupZoneTable,PrecId + "  CABIN    C",logInfo);
                logInfo.pass("I check cabin item in group zone table");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                ModifyGroupZoneTable = "PAG*";
                gl.logCommand(logInfo,ModifyGroupZoneTable);
                gl.sendCmdValidateResponse(ModifyGroupZoneTable,PrecId + "  CABIN    C",logInfo);
                logInfo.pass("I check cabin item in group zone table");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if(ModifyType.equalsIgnoreCase("DeleteItemGroupZoneTable")){
                String DeleteItemGroupZoneTable = "PAGD1";
                gl.logCommand(logInfo,DeleteItemGroupZoneTable);
                gl.sendCmdValidateResponse(DeleteItemGroupZoneTable,"REMOVING 0001 ITEM(S)",logInfo);
                logInfo.pass("I delete cabin item in group zone table");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                DeleteItemGroupZoneTable = "PAGD1" + "\n" + "PLEASE CONFIRM -Y/N- Y";
                gl.sendCopiedCmdValidateResponse2i(logInfo,DeleteItemGroupZoneTable,"CABIN    C",PrecId);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                isharesPageObjects1.FORMSIZE_DROPDOWN.click();
                isharesPageObjects1.FORMSIZE_SELECT1.click();

                DeleteItemGroupZoneTable = "PAG*";
                gl.logCommand(logInfo,DeleteItemGroupZoneTable);
                gl.sendCmdValidateResponse(DeleteItemGroupZoneTable,logInfo);
                logInfo.pass("I check deleted cabin item in group zone table");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                if(Response.contains(PrecId + "  CABIN    C")){
                    Assert.fail();
                }
            }



        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }




