    public void addMessageToPax(ExtentTest logInfo) {
        try {

            for(int i=0;i<mFName.get(getDriverID()).length;i++){
                //     6:TM499/03FEBPTY-TEST/OOO
                String TextCommand = "6:TM" + mFlightNumber.get(getDriverID()) + "/"
                        + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID())) + mOriginCity.get(getDriverID()) + "-"
                        + mFName.get(getDriverID())[i] + "/" + mLName.get(getDriverID())[i] + "\n" + "CALL ME BACK";

                isharesPageObjects1.FORMSIZE_DROPDOWN.click();
                isharesPageObjects1.FORMSIZE_SELECT2.click();
                gl.logCommand(logInfo,TextCommand);
                isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA.click();
                gl.copyCmdToClipboardAndPaste(TextCommand,isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);
                isharesPageObjects1.SEND_ISHARES.click();
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                gl.waitForProfileLoad();
                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                Assert.assertTrue(response.contains("OK"));
                isharesPageObjects1.FORMSIZE_DROPDOWN.click();
                isharesPageObjects1.FORMSIZE_SELECT1.click();

                // gl.sendCopiedCmdValidateResponse2(TextCommand,"OK");

            }

        } catch (Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

    public void addMessageToMultiplePax(ExtentTest logInfo) {
        try {

            System.out.println("mFname length " + mFName.get(getDriverID()).length);

            //     6:TM499/03FEBPTY-TEST/OOO
            Faker faker = new Faker(new Locale("en-US"));
            String Message = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "");

            for(int i=0;i<mFName.get(getDriverID()).length;i++) {

                String TextCommand = "6:TM" + mFlightNumber.get(getDriverID()) + "/"
                        + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID())) + mOriginCity.get(getDriverID()) + "-"
                        + mFName.get(getDriverID())[i] + "/" + mLName.get(getDriverID())[i] + "\n" + Message;

                gl.logCommand(logInfo, TextCommand);
                gl.sendCopiedCmdValidateResponse2i(logInfo, TextCommand, "MULTIPLE ITEMS", "-OK-");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                String response = isharesPageObjects1.SHARES_RESPONSE.getText();

                if (response.contains("MULTIPLE ITEMS")) {
                    // Checking PNR in multiple item list
                    for (int j = 0; j < 7; j++) {
                        if (response.contains(mOrderNumber.get(getDriverID()))) {
                            response = isharesPageObjects1.SHARES_RESPONSE.getText();
                            break;
                        } else {
                            gl.sendCmdValidateResponse2("MD",logInfo);
                            response = isharesPageObjects1.SHARES_RESPONSE.getText();
                        }
                    }
                    //Capturing ID for the PNR
                    int index = response.indexOf(mOrderNumber.get(getDriverID()));
                    String indexVal = response.substring((index - 27), (index - 24)).trim();
                    CurrentwindowID.put(getDriverID(), indexVal);

                    //6:LTM-130
                    //M	BAGGAGE LOST
                    String ModifiedMessage = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "");
                    String MultiListCmd = "6:LTM-" + indexVal + "\n" + ModifiedMessage; // Selected pax with ID
                    gl.logCommand(logInfo, MultiListCmd);
                    gl.sendCopiedCmdValidateResponse2i(logInfo, MultiListCmd, "002", "-OK- ");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    gl.waitForProfileLoad();

                    String CheckinCommand = "6:LK-" + indexVal + "\n" + "B0"; // Selected pax with ID
                    gl.logCommand(logInfo, CheckinCommand);
                    gl.sendCopiedCmdValidateResponse2i(logInfo, CheckinCommand, "UNDELIVERED MESSAGES", "FLT NOT OPEN");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    gl.waitForProfileLoad();
                    String response1 = isharesPageObjects1.SHARES_RESPONSE.getText();

                    if (response1.contains("FLT NOT OPEN")) {
                        openFlight(logInfo, mFlightNumber.get(getDriverID()), sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID())), mOriginCity.get(getDriverID()));
                        gl.logCommand(logInfo, TextCommand);
                        gl.sendCopiedCmdValidateResponse2i(logInfo, CheckinCommand, "UNDELIVERED MESSAGES", mFName.get(getDriverID())[0].toUpperCase());
                    }
                }

            }
            gl.ignoreTRNS(logInfo);

        } catch (Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

