    public String[] mergeArrays(List<String> Arr1, String[] Arr2)
    {
        int length = Arr1.size() + Arr2.length; //add the length of firstArray into secondArray
        String[] mergedArray = new String[length];
        int pos=0;
        for (String element : Arr1) //copying elements of secondArray using for-each loop
        {
            mergedArray[pos] = element;
            pos++;              //increases position by 1
        }
        for (String element : Arr2) //copying elements of firstArray using for-each loop
        {
            mergedArray[pos] = element;
            pos++;
        }
        return mergedArray;
    }

    public void AddFFNumbers(List<String> FFNumbers,List<String> Fnames,List<String> LNames,HashMap<String,String> Paxtype, String otherPax,ExtentTest logInfo)
    {
        try {
            misFQTV.put(getDriverID(),Boolean.TRUE);

            mFFnumbers.put(getDriverID(),FFNumbers);
            mFF_FirstNames.put(getDriverID(),Fnames);
            mFF_LastNames.put(getDriverID(),LNames);
            mFF_PaxType.put(getDriverID(),Paxtype);
            ArrayList<String> PaxNameList = new ArrayList<String>();

            String[] paxtype = new String[mFF_FirstNames.get(getDriverID()).size()];
            for(int i=0;i<mFF_FirstNames.get(getDriverID()).size();i++){
                paxtype[i] = "Adult";
            }

            for(int i=0;i< mFF_FirstNames.get(getDriverID()).size();i++){
                String command = "-" + mFF_FirstNames.get(getDriverID()).get(i) + "/" + mFF_LastNames.get(getDriverID()).get(i)
                        + "*" + mFFnumbers.get(getDriverID()).get(i);

                System.out.println(command);
                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command, mFF_FirstNames.get(getDriverID()).get(i).toUpperCase(), mFF_LastNames.get(getDriverID()).get(i).toUpperCase(),"SYSTEM/LINK UNAVAIL - NAME NOT VERIFIED", logInfo);
                if(isharesPageObjects1.SHARES_RESPONSE.getText().contains("SYSTEM/LINK UNAVAIL - NAME NOT VERIFIED"))
                {
                    logInfo.info(MarkupHelper.createLabel("SYSTEM/LINK UNAVAIL - NAME NOT VERIFIED", ExtentColor.PURPLE));
                    Assert.fail("SYSTEM/LINK UNAVAIL - NAME NOT VERIFIED");
                }
            }

            if(otherPax.equalsIgnoreCase("Without"))
            {
                mFName.put(getDriverID(),Fnames.toArray(new String[0]));
                mLName.put(getDriverID(),LNames.toArray(new String[0]));
                mPaxName_PaxType.put(getDriverID(),Paxtype);
                mPaxNameList.put(getDriverID(), PaxNameList);
                mPaxType.put(getDriverID(), paxtype);
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }

    }


