    public void requestForSeatMap(ExtentTest logInfo, String seatMapType, String COS) {
        try {

            if(seatMapType.equalsIgnoreCase("Horizontal")) {
                String command = "6:CMH";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "002-OK- H", "IGN TRANS",logInfo);
                if(isharesPageObjects1.SHARES_RESPONSE.getText().contains("IGN TRANS")){
                    gl.sendCmdValidateResponse("I",logInfo);
                    gl.sendCmdValidateResponse(command, "002-OK- H",logInfo);
                }
            }

            else if(seatMapType.equalsIgnoreCase("Vertical")) {
                String command = "6:CMV";
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "002-OK- V", "IGN TRANS",logInfo);
                if(isharesPageObjects1.SHARES_RESPONSE.getText().contains("IGN TRANS")){
                    gl.sendCmdValidateResponse("I",logInfo);
                    gl.sendCmdValidateResponse(command, "002-OK- V",logInfo);
                }
            }
            else if(seatMapType.equalsIgnoreCase("ReturnFlight")) {
                String command2 = "6:*" + mConnectingFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegTwo.get(getDriverID()))
                        + mConnectedfromCity.get(getDriverID()) + "." + COS;
                gl.sendCmdValidateResponse(command2, mConnectedfromCity.get(getDriverID()).toUpperCase() + "-" + mOriginCity.get(getDriverID()).toUpperCase(),"@-AVAIL  .-TAKEN",logInfo);

            }
            //            6:*302/18JANPTY.Y
            String command2 = "6:*" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                    + mOriginCity.get(getDriverID()) + "." + COS;
            gl.sendCmdValidateResponse(command2, mOriginCity.get(getDriverID()).toUpperCase() + "-" + mDestinationcity.get(getDriverID()).toUpperCase(),"@-AVAIL  .-TAKEN",logInfo);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

    public void AssignSeatAfterCheckin(ExtentTest logInfo,String AssignSeatType, String COS) {
        try {

            String Seatcmd = "";
            String[] SeatNumber = new String[totalPax];
            boolean SeatAssigned = false;
            String[] SeatAlphabet= {"A","F"};

            //            6:*302/18JANPTY.Y
            String command2 = "6:*" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                    + mOriginCity.get(getDriverID()) + "." + COS;
            gl.logCommand(logInfo,command2);
            gl.sendCmdValidateResponse(command2, mOriginCity.get(getDriverID()).toUpperCase() + "-" + mDestinationcity.get(getDriverID()).toUpperCase(),"@-AVAIL  .-TAKEN",logInfo);
            gl.ignoreTRNS(logInfo);

            for(int j=0;j<totalPax;j++)
            {
                gl.ignoreTRNS(logInfo);
                for (String Alphabet : SeatAlphabet)
                {
                    for (int i = 5; i <= 35; i++)
                    {
                        //6:409/10JULSFO-TEST/PERRY#@35A
                        if(AssignSeatType.equalsIgnoreCase("ReplaceSeatAfterCheckin")){
                            Seatcmd = "6:" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                                    + mOriginCity.get(getDriverID()) + "-" + mFName.get(getDriverID())[j] + "/" + mLName.get(getDriverID())[j]
                                    + "|@" + i + Alphabet;
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd,logInfo);
                            logInfo.pass("I assign seat");
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        }
                        else if(AssignSeatType.equalsIgnoreCase("heldSeatAfterCheckin")){
                            Seatcmd = "6:H" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                                    + mOriginCity.get(getDriverID()) + "-" + mFName.get(getDriverID())[j] + "/" + mLName.get(getDriverID())[j]
                                    + "|" + i + Alphabet;
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd,logInfo);
                            logInfo.pass("I assign held seat");
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        }
                        else if(AssignSeatType.equalsIgnoreCase("BlockSeatAndAssign")){
                            // 6:CB809/21SEPPTY.Y#@35A
                            Seatcmd = "6:CB" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                                    + mOriginCity.get(getDriverID()) + "." + COS
                                    + "|" + i + Alphabet;
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd,logInfo);
                            logInfo.pass("I block the seat");
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        }
                        else if(AssignSeatType.equalsIgnoreCase("InoperativeSeat")){
                            // 6:CI816/10JULPTY.Y#05F
                            Seatcmd = "6:CI" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                                    + mOriginCity.get(getDriverID()) + "." + COS
                                    + "|" + i + Alphabet;
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd,logInfo);
                            logInfo.pass("I block the seat");
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        }

                        String Response = isharesPageObjects1.SHARES_RESPONSE.getText();

                        if(Response.contains("FLT NOT OPEN") || Response.contains("SHIP NOT ASSIGNED")){
                            openFlight(logInfo, mFlightNumber.get(getDriverID()), sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID())), mOriginCity.get(getDriverID()));
                            isharesPageObjects1.FORMSIZE_DROPDOWN.click();
                            isharesPageObjects1.FORMSIZE_SELECT1.click();
                            gl.logCommand(logInfo,Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd,logInfo);
                            Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                        }

                        if (Response.contains(i + Alphabet))
                        {
                            SeatNumber[j] = i + Alphabet;
                            SeatAssigned=true;
                            gl.logCommand(logInfo,"*" + mOrderNumber.get(getDriverID()));
                            gl.sendCmdValidateResponse("*" + mOrderNumber.get(getDriverID()),SeatNumber[j],logInfo);
                            gl.logCommand(logInfo,command2);
                            gl.sendCmdValidateResponse(command2,logInfo);
                            logInfo.pass("I validated seat assigned successfully");
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            break;
                        }

                        if (Response.contains("002-OK-"))
                        {
                            SeatNumber[j] = i + Alphabet;
                            SeatAssigned=true;
                            gl.logCommand(logInfo,command2);
                            gl.sendCmdValidateResponse(command2,logInfo);
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            //6:CB809/21SEPPTY.Y#@35A
                            Seatcmd = "6:CB" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                                    + mOriginCity.get(getDriverID()) + "." + COS
                                    + "|@" + SeatNumber[j];
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd,"002-OK-",logInfo);
                            logInfo.pass("I unblock the seat");
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                            gl.sendCmdValidateResponse("*" + mOrderNumber.get(getDriverID()),logInfo);
                            String cmd = "6:A|" + SeatNumber[j];
                            gl.logCommand(logInfo,cmd);
                            gl.sendCmdValidateResponse(cmd,SeatNumber[j] +"*",  logInfo);
                            logInfo.pass("I verified if ghost seat is not assigned to passenger");
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            gl.logCommand(logInfo,"6P#ER");
                            gl.sendCmdValidateResponse("6P#ER",SeatNumber[j] +"*","6P#ER",logInfo);
                            gl.logCommand(logInfo,"ER");
                            gl.sendCmdIfRequired("ER",SeatNumber[j] +"*",logInfo);
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            break;
                        }
                        if (Response.contains("INOP PROCESSED")) {
                            SeatNumber[j] = i + Alphabet;
                            SeatAssigned=true;
                            logInfo.pass("I validated seat InOperated successfully");
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            break;
                        }
                        if(AssignSeatType.equalsIgnoreCase("AssignSpecificSeat")){
                            gl.sendCmdValidateResponse("*" + mOrderNumber.get(getDriverID()),logInfo);
                            Seatcmd = "6:A|" + i + Alphabet;
                            gl.logCommand(logInfo, Seatcmd);
                            gl.sendCmdValidateResponse(Seatcmd,logInfo);
                            logInfo.pass("I assign held seat");
                            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                            String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                            if (response.contains(i + Alphabet+ "*")) {
                                SeatNumber[j] = i + Alphabet;
                                SeatAssigned=true;
                                gl.logCommand(logInfo,"6P#ER");
                                gl.sendCmdValidateResponse("6P#ER",SeatNumber[j] +"*","6P#ER",logInfo);
                                gl.logCommand(logInfo,"ER");
                                gl.sendCmdIfRequired("ER",SeatNumber[j] +"*",logInfo);
                                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                                break;
                            }
                        }

                    }
                    if(SeatAssigned==true){
                        break;
                    }
                }
            }

            mSeatNumber.put(getDriverID(), SeatNumber);

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

