    public void searchavailabilityForSegSix(ExtentTest logInfo, String Origin, String Destination, String date, String totalpax, String COS, String airline) {

        String command = null;
        try {

            //A PTYLAX 10NOV-CM
            String Date = date.substring(0, 2);
            int departdate = Integer.parseInt(Date);
            int flag = 0;

            while(departdate <= mSharesStartDateSegFive.get(getDriverID())) {
                departdate++;
            }
            //if depart date is greate than 3st segment then only t should select flight
            String[] economyClass = {"Y", "H", "B", "M"};
            String[] businessClass = {"C", "J", "D", "R"};
            String[] destinationCities = {"MIA", "HAV", "MEX"};

            // Include primary destination first, then fallback destinations
            String[] allDestinations = new String[destinationCities.length + 1];
            allDestinations[0] = Destination;
            System.arraycopy(destinationCities, 0, allDestinations, 1, destinationCities.length);

            if(COS.contains("Y") || COS.contains("B") || COS.contains("H") || COS.contains("M")|| COS.contains("W")||
                    COS.contains("K")|| COS.contains("Q") || COS.contains("E") || COS.contains("F"))
            {
                for (String currentDestination : allDestinations) { // Iterate through destinations
                    for (String tcos : economyClass) { // Iterate through all classes in economyClass
                        COS = tcos;
                        for (int i = departdate; i <= departdate + 5; i++) {  // loop for date

                            String DateFormatted = gl.plusDaysFromTodayNew(i);
                            LocalDateTime departuredate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
                            String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departuredate.toLocalDate());

                            mSharesStartDateSegSix.put(getDriverID(), i); //storing this value to check Other segment date should be greater than this date
                            System.out.println(DateFormatted + "Date in map");

                            if (airline.equalsIgnoreCase("CM")) {
                                command = "A " + Origin + currentDestination + " " + departureDateFormatted + "-" + "CM";
                            } else if (airline.equalsIgnoreCase("UA")) {
                                command = "A " + Origin + currentDestination + " " + departureDateFormatted + "-" + "UA";
                            }
                            gl.logCommand(logInfo, command);
                            gl.sendCmdValidateResponse(command, logInfo);

                            String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                            gl.checkForErrors(command,Response,logInfo);

                            flightIndex.put(getDriverID(),getFlightPositions(Response,airline));

                            for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++) {  //loop for flight

                                String command2 = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j-1); //N2Y1
                                gl.logCommand(logInfo, command2);
                                gl.sendCmdValidateResponse(command2, logInfo);
                                System.out.println(command2);
                                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                                gl.checkForErrors(command2,response,logInfo);

                                if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") || response.contains(Origin + currentDestination)) {

                                    flag = 1;
                                    break;
                                } else {
                                    gl.logCommand(logInfo, command2);
                                    gl.sendCmdValidateResponse(command2, logInfo);
                                    gl.checkForErrors(command2,isharesPageObjects1.SHARES_RESPONSE.getText(),logInfo);
                                }
                            }
                            if (flag == 1) {   // Breaking Depart Date loop
                                break;
                            }
                        }
                        if (flag == 1) {   // Breaking Depart COS loop
                            break;
                        }
                    }
                    if (flag == 1) {   // Breaking Destination Market loop
                        break;
                    }
                }
            }
            else if(COS.contains("C") || COS.contains("J") || COS.contains("D") || COS.contains("R")) {
                for (String currentDestination : allDestinations) { // Iterate through destinations
                    for (String tcos : businessClass) { // Iterate through all classes in economyClass
                        COS = tcos;
                        for (int i = departdate; i <= departdate + 5; i++) {  // loop for date

                            String DateFormatted = gl.plusDaysFromTodayNew(i);
                            LocalDateTime departuredate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
                            String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departuredate.toLocalDate());

                            mSharesStartDateSegSix.put(getDriverID(), i); //storing this value to check Other segment date should be greater than this date
                            System.out.println(DateFormatted + "Date in map");

                            if (airline.equalsIgnoreCase("CM")) {
                                command = "A " + Origin + currentDestination + " " + departureDateFormatted + "-" + "CM";
                            } else if (airline.equalsIgnoreCase("UA")) {
                                command = "A " + Origin + currentDestination + " " + departureDateFormatted + "-" + "UA";
                            }
                            gl.logCommand(logInfo, command);
                            gl.sendCmdValidateResponse(command, logInfo);

                            String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
                            gl.checkForErrors(command,Response,logInfo);

                            flightIndex.put(getDriverID(),getFlightPositions(Response,airline));

                            for (int j = 1; j <= flightIndex.get(getDriverID()).size(); j++) {  //loop for flight

                                String command2 = "N" + totalpax + COS + flightIndex.get(getDriverID()).get(j-1); //N2Y1 //N2Y1
                                gl.logCommand(logInfo, command2);
                                gl.sendCmdValidateResponse(command2, logInfo);
                                System.out.println(command2);
                                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                                gl.checkForErrors(command2,response,logInfo);

                                if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") || response.contains(Origin + currentDestination)) {

                                    flag = 1;
                                    break;
                                } else {
                                    gl.logCommand(logInfo, command2);
                                    gl.sendCmdValidateResponse(command2, logInfo);
                                    gl.checkForErrors(command2,isharesPageObjects1.SHARES_RESPONSE.getText(),logInfo);
                                }
                            }
                            if (flag == 1) {   // Breaking Depart Date loop
                                break;
                            }
                        }
                        if (flag == 1) {   // Breaking Depart COS loop
                            break;
                        }
                    }
                    if (flag == 1) {   // Breaking Destination Market loop
                        break;
                    }
                }
            }

            logInfo.pass("Search for availability for sixth segment");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }


