    public void flightAvailability(ExtentTest logInfo,String Origin,String Destination,String Date){

        try{
//           A12AUGPTYIAH1A-CM/UA
            int date = Integer.parseInt(Date.substring(0,2));
            boolean FlightSeachDisplayed = false;
            for(int i=0;i<=5;i++){
                String flightAvailability = "A" + sharesFormatDateFromGUI(date) + Origin + Destination
                        + "1A-CM/UA";
                gl.logCommand(logInfo,flightAvailability);
                gl.sendCmdValidateResponse(flightAvailability,logInfo);
                String Response = isharesPageObjects1.SHARES_RESPONSE.getText();

                if(Response.contains("CM") || Response.contains("UA")){
                    FlightSeachDisplayed = true;
                    break;
                }else{
                    date = date + 1;
                    gl.sendCmdValidateResponse(flightAvailability,sharesFormatDateFromGUI(date),"CM","UA",logInfo);
                }
                logInfo.pass("I search flight availability");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            if(!FlightSeachDisplayed){
                Assert.fail();
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }


