    public void performMassTransfer(ExtentTest logInfo) {

        try{
//        6:MT<New flight>/<DOJ><ORIGIN>.<OLD FIGHT>/<DOJ><ORIGIN>#ALL
//        6:MT415/03MARPTY.243/03MARPTY#ALL

            gl.ignoreTRNS(logInfo);
            String massTransferCmd = "6:MT" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID())) + mOriginCity.get(getDriverID())
                    + "." + mAltFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mAltrFlightDays.get(getDriverID())) + mOriginCity.get(getDriverID()) + "|ALL";

            System.out.println("CMD: " + massTransferCmd);
            gl.logCommand(logInfo,massTransferCmd);
            gl.sendCmdValidateResponse(massTransferCmd, "MOVE FROM FLIGHT", "SHIP NOT ASSIGNED",logInfo);

            if(isharesPageObjects1.SHARES_RESPONSE.getText().contains("SHIP NOT ASSIGNED")){
                isharesPageObjects1.COMMAND_INPUTAREA_ISHARES.sendKeys(Keys.CONTROL + "a" + Keys.BACK_SPACE);
                openFlight(logInfo, mFlightNumber.get(getDriverID()), sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID())),
                        mOriginCity.get(getDriverID()));

                isharesPageObjects1.FORMSIZE_DROPDOWN.click();
                isharesPageObjects1.FORMSIZE_SELECT1.click();
                gl.waitForProfileLoad();

                gl.logCommand(logInfo,massTransferCmd);
                gl.sendCmdValidateResponse(massTransferCmd, "MOVE FROM FLIGHT  " + mAltFlightNumber.get(getDriverID()) + " TO FLIGHT  " + mFlightNumber.get(getDriverID()),logInfo);
            }

            isharesPageObjects1.FORMSIZE_DROPDOWN.click();
            isharesPageObjects1.FORMSIZE_SELECT2.click();
            isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA.sendKeys(Keys.CONTROL + "a" + Keys.BACK_SPACE);

            System.out.println("Flight Coammand" + massTransferCmd);
            String deleteAccept = "PLEASE CONFIRM -Y/N- Y" ;
            String MassTransfer = massTransferCmd + "\n" + deleteAccept;
            System.out.println("MassTransfer \n" + MassTransfer);

            gl.sendCopiedCmdValidateResponse2(logInfo,MassTransfer, "ALL PROCESSED", "TRANSFERRED");

            logInfo.pass("I perform mass transfer for all the passengers");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

