            gl.sendCmdValidateResponse(saveAndRetrieve, "6P#ER *",mOrderNumber.get(getDriverID()),logInfo);
            gl.logCommand(logInfo,saveAndRetrieve);

            gl.sendCmdIfRequired(endAndretrieve, mOrderNumber.get(getDriverID()),logInfo);
            gl.logCommand(logInfo,endAndretrieve);

