    public void makeThePassengerVolunteer(ExtentTest logInfo){

        try{
            gl.ignoreTRNS(logInfo);
            gl.waitForProfileLoad();
            //6-DV<Flight#>-<Pax Name>

            for(int i=0;i<mFName.get(getDriverID()).length;i++) {

                String makeThePassengerVolunteer = "6:DV" + mFlightNumber.get(getDriverID()) + "/" +
                        getSharesDate() + mOriginCity.get(getDriverID() ) + "-"
                        + mFName.get(getDriverID())[i] + "/" +  mLName.get(getDriverID())[i];

                gl.logCommand(logInfo, makeThePassengerVolunteer);
                gl.sendCmdValidateResponse(makeThePassengerVolunteer, "VOL-SB","PSGR ADDED TO VOL OVERSOLD LIST","MULTIPLE ITEMS",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                String Reponse = isharesPageObjects1.SHARES_RESPONSE.getText();

                if(Reponse.contains("MULTIPLE ITEMS")){
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String response1 = isharesPageObjects1.SHARES_RESPONSE.getText();

                    // Checking PNR in multiple item list
                    for(int j=0;j<7;j++){
                        if(response1.contains(mOrderNumber.get(getDriverID()))){
                            response1 = isharesPageObjects1.SHARES_RESPONSE.getText();
                            break;
                        }
                        else{
                            gl.sendCmdValidateResponse24("MD",logInfo);
                            response1 = isharesPageObjects1.SHARES_RESPONSE.getText();
                        }
                    }
                    //Capturing ID for the PNR
                    int index = response1.indexOf(mOrderNumber.get(getDriverID()));
                    String indexVal = response1.substring((index-27),(index-24)).trim();

                    String MultiListCmd = "6:LDV-" + indexVal; // Selected pax with ID
                    gl.logCommand(logInfo,MultiListCmd);
                    gl.sendCmdValidateResponse(MultiListCmd, "PSGR ADDED TO VOL OVERSOLD LIST","VOL-SB",logInfo);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }

            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

