    public void searchavailabilitySpecialPnrTakingDifferentFlt(ExtentTest logInfo,String PNRType, String Origin, String Destination, String date, String totalpax, String COS,String airline) {

        try {

            //A PTYLAX 10NOV-CM
            String Date = date.substring(0, 2);
            int departdate = Integer.parseInt(Date);
            int flag = 0;

            String departureDateFormatted = sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()));

//                    mSharesStartDateSegTwo.put(getDriverID(), i); //storing this value to check Other segment date should be greater than this date
            System.out.println(departureDateFormatted + "Date in map");
            mFlightDepartDate.put(getDriverID(), departureDateFormatted);

            String command = null;

            if (airline.equalsIgnoreCase("CM")) {
                command = "A " + Origin + mDestinationcity.get(getDriverID()) + " " + departureDateFormatted + "-" + "CM";
            }
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command,logInfo);

            String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
            gl.checkForErrors(command,Response,logInfo);

            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            int maxValue = 3;
            for (int j = 1; j <= maxValue; j++) {  //loop for flight

                String command2 = null;
                if (PNRType.equalsIgnoreCase("Group")) {

                    command2 = "N" + totalpax + COS + j + "GNN"; //N2Y1

                } else if (PNRType.equalsIgnoreCase("NRSA")) {

                    command2 = "N" + totalpax + COS + j + "MM";
                } else if (PNRType.equalsIgnoreCase("WaitList")) {

                    command2 = "N" + totalpax + COS + j + "PD";
                } else if (PNRType.equalsIgnoreCase("NRPS")) {
                    command2 = "N" + totalpax + COS + j + "PNN";
                }
                gl.logCommand(logInfo, command2);
                gl.sendCmdValidateResponse(command2,logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                gl.checkForErrors(command2,response,logInfo);

                if (response.contains("ETKT ELIGIBLE") && !mFlightNumber.get(getDriverID()).equalsIgnoreCase(response.substring(7,10))) {

                    mFlightNumber.put(getDriverID(), response.substring(7, 10));
                    System.out.println("FFlight number " + response.substring(7, 10));

                    flag = 1;
                    break;


                } else {

                    if(j==3){
                        maxValue = 6;
                        j = 1;
                        gl.sendCmdValidateResponse("A*",logInfo);
                    }
                    else {
                        gl.logCommand(logInfo, command);
                        gl.sendCmdValidateResponse(command,logInfo);
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        gl.checkForErrors(command,isharesPageObjects1.SHARES_RESPONSE.getText(),logInfo);
                    }
                }
                if(flag==1){
                    break;
                }

            }

            logInfo.pass("Search for availability");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }


    public void searchavailabilityTakingDifferentFlt(ExtentTest logInfo, String Origin, String Destination, String date, String totalpax, String COS,String airline) {
        try {
            //A PTYLAX 10NOV-CM
            String Date = date.substring(0, 2);
            int departdate = Integer.parseInt(Date);
            int flag = 0;

            String departureDateFormatted = sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()));

//                    mSharesStartDateSegTwo.put(getDriverID(), i); //storing this value to check Other segment date should be greater than this date
            System.out.println(departureDateFormatted + "Date in map");
            mFlightDepartDate.put(getDriverID(), departureDateFormatted);

            String command = null;

            if (airline.equalsIgnoreCase("CM")) {
                command = "A " + Origin + mDestinationcity.get(getDriverID()) + " " + departureDateFormatted + "-" + "CM";
            }
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command,logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
            gl.checkForErrors(command,Response,logInfo);

            flightIndex.put(getDriverID(),getFlightPositions(Response,airline));

            int maxValue = 3;
            for (int j = 1; j <= maxValue; j++) {  //loop for flight

                String command2 = "N" + totalpax + COS + j; //N2Y1
                gl.logCommand(logInfo,command2);
                gl.sendCmdValidateResponse(command2,logInfo);

                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                gl.checkForErrors(command2,response,logInfo);



                if (response.contains("ETKT ELIGIBLE") && !mFlightNumber.get(getDriverID()).equalsIgnoreCase(response.substring(6,10))) {

                    mFlightNumber.put(getDriverID(), response.substring(7, 10).trim());
                    System.out.println("FFlight number " + response.substring(7, 10));
                    mCOS.put(getDriverID(),COS);
                    flag = 1;
                    break;

                } else {

                    if(j==3){
                        maxValue = 6;
                        j = 1;
                        gl.sendCmdValidateResponse("A*",logInfo);
                    }
                    else {
                        gl.logCommand(logInfo, command);
                        gl.sendCmdValidateResponse(command,logInfo);
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        gl.checkForErrors(command,isharesPageObjects1.SHARES_RESPONSE.getText(),logInfo);
                    }
                }
                if(flag==1){
                    break;
                }
            }
            logInfo.pass("Search for availability");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

