    public void marketingFlightCheckin(ExtentTest logInfo, String noOfBags, String baggageWeight){
        try{
//            6:1931/11JUNPTY-TEST/ONE
//            B0  or B1/20
            gl.ignoreTRNS(logInfo);
            String checkinCmd = null;

            isharesPageObjects1.FORMSIZE_DROPDOWN.click();
            isharesPageObjects1.FORMSIZE_SELECT2.click();
            gl.waitForProfileLoad();

            for(int i=0; i<mFName.get(getDriverID()).length; i++)
            {
                if(noOfBags.equalsIgnoreCase("0"))
                {
                    checkinCmd = "6:" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                            + mOriginCity.get(getDriverID()) + "-" + mFName.get(getDriverID())[i] + "/" + mLName.get(getDriverID())[i] + "\n" + "B0";
                }
                else
                {
                    checkinCmd = "6:" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                            + mOriginCity.get(getDriverID()) + "-" + mFName.get(getDriverID())[i] + "/" + mLName.get(getDriverID())[i] + "|12D" + "\n" + "B" + noOfBags
                            + "/" + baggageWeight;
                }

                gl.logCommand(logInfo, checkinCmd);

                isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA.click();
                gl.copyCmdToClipboardAndPaste(checkinCmd,isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);
                isharesPageObjects1.SEND_ISHARES.click();
                gl.waitForProfileLoad();
                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                gl.logResponse(logInfo,response);
                Assert.assertTrue(response.contains("UNABL TO PROCESS-CODE SHARE FLIGHT") || response.contains("FLT NOT OPEN"));

                if(isharesPageObjects1.SHARES_RESPONSE.getText().contains("FLT NOT OPEN")){

                    openFlight(logInfo, mFlightNumber.get(getDriverID()), sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID())), mOriginCity.get(getDriverID()));

                    isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA.click();

                    gl.logCommand(logInfo, checkinCmd);
                    gl.copyCmdToClipboardAndPaste(checkinCmd,isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);
                    isharesPageObjects1.SEND_ISHARES.click();
                    gl.waitForProfileLoad();
                    response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    gl.logResponse(logInfo,response);
                    Assert.assertTrue(response.contains("UNABL TO PROCESS-CODE SHARE FLIGHT"));

                }
            }

            logInfo.pass("I do the checkin of shares PNR for a marketing flight and validate the error");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }



