    public void saveConnectingFltNumber(ExtentTest logInfo){
        try {

            String connectingFlight = null;
            String connectingCity = null;

            gl.sendCmdValidateResponse("*" + mOrderNumber.get(getDriverID()),logInfo);

            String response = isharesPageObjects1.SHARES_RESPONSE.getText();

            String[] rawResponse = response.split("\n");

            for (int i = 0; i < rawResponse.length; i++) {
                String[] splitResponse = rawResponse[i].split(" ");
                for (int j = 0; j < splitResponse.length; j++) {
                    if (splitResponse.length > 1) {
                        if (splitResponse[1].equalsIgnoreCase("2")) {
                            connectingFlight = splitResponse[3].replaceAll("[^0-9]", "");
                            System.out.println("Connecting Flight: " + connectingFlight);

                            connectingCity = splitResponse[6].substring(0,3);
                            System.out.println("Connecting Market: " + connectingCity);
                            break;
                        }
                    }
                }
                if (connectingFlight != null)
                    break;
            }

            mConnectingFlightNumber.put(getDriverID(), connectingFlight);
            mConnectedfromCity.put(getDriverID(), connectingCity);

            logInfo.pass("I verify seat map summary");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

