    public void changeNameOfAllThePassengers(ExtentTest logInfo) {
        try {

            int totalpaxCount = mFName.get(getDriverID()).length;
            int paxcount = totalpaxCount;

            Faker faker = new Faker(new Locale("en-US"));
            FName = new String[paxcount];
            mFName.put(getDriverID(), FName);

            LName = new String[paxcount];
            mLName.put(getDriverID(), LName);

            for(int i=0; i<totalpaxCount; i++) {

                FName[i] = faker.name().firstName().replaceAll("[^a-zA-Z0-9]", "");
                LName[i] = faker.name().lastName().replaceAll("[^a-zA-Z0-9]", "");

                String command1 = "-" + (i+1) + "@" + FName[i] + "/" + LName[i];
                System.out.println("Command: " + command1);

                gl.logCommand(logInfo, command1);
                gl.sendCmdValidateResponse(command1, command1.toUpperCase(),logInfo);

                logInfo.pass("I change the name of the passenger for adult");

                gl.logCommand(logInfo, saveAndRetrieve);
                gl.sendCmdValidateResponse(saveAndRetrieve,logInfo);

                gl.logCommand(logInfo, endAndretrieve);
                gl.sendCmdIfRequired(endAndretrieve,mOrderNumber.get(getDriverID()),logInfo);
                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                Assert.assertTrue(response.contains(FName[i].toUpperCase() + "/" + LName[i].toUpperCase()) || response.contains("WARNING - TRANSACT WILL UNSEAT CKD-IN PSGR"));

                if(response.contains("WARNING - TRANSACT WILL UNSEAT CKD-IN PSGR")){
                    gl.logCommand(logInfo, endAndretrieve);
                    gl.sendCmdValidateResponse(endAndretrieve, mOrderNumber.get(getDriverID()),logInfo);
                }
            }

            mFName.put(getDriverID(), FName);
            mLName.put(getDriverID(), LName);


        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

