    public void performUnCheckinBaggage(ExtentTest logInfo){

        try{

            //            6:226/08AUGPTY-TIM/LEE#@
            for(int j=0;j<mFName.get(getDriverID()).length;j++){
                String performUnCheckinBaggage = "6:" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                        +mOriginCity.get(getDriverID()) + "-" + mFName.get(getDriverID())[j] + "/" + mLName.get(getDriverID())[j]
                        + "|@";
                gl.logCommand(logInfo,performUnCheckinBaggage);
                gl.sendCmdValidateResponse(performUnCheckinBaggage,"SEATS UNASSIGNED",logInfo);
                logInfo.pass("I perform UnCheckin Baggage");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            //6:BTAG226/08AUGPTY
            String performUnCheckinBaggage = "6:BTAG" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                    +mOriginCity.get(getDriverID());
            gl.logCommand(logInfo,performUnCheckinBaggage);
            gl.sendCmdValidateResponse(performUnCheckinBaggage,"BAGGAGE TAG",logInfo);
            logInfo.pass("I check Baggage is removed");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if(isharesPageObjects1.SHARES_RESPONSE.getText().contains(mFName.get(getDriverID())[0].toUpperCase())){
                Assert.fail();
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }


