    public void enterparticularDetails(ExtentTest logInfo, String paxCount) {
        try {
            int pcount = Integer.parseInt(paxCount);
            for(int i=0;i<pcount;i++) {
                String cmd = "";
                if (mPaxName_PaxType.get(getDriverID()).get(mPaxNameList.get(getDriverID()).get(i)).equalsIgnoreCase("Adult")) {
                    cmd = "-" + mFName.get(getDriverID())[i] + "/" + mLName.get(getDriverID())[i];
                }
                else if (mPaxName_PaxType.get(getDriverID()).get(mPaxNameList.get(getDriverID()).get(i)).equalsIgnoreCase("Child")) {
                    cmd =  "-" + mFName.get(getDriverID())[i] + "/" +mLName.get(getDriverID())[i] + "*-CHD06";

                } else if (mPaxName_PaxType.get(getDriverID()).get(mPaxNameList.get(getDriverID()).get(i)).equalsIgnoreCase("Inf")) {

                    String dob = gl.generateDateOfBirthNew("Inf");
                    cmd = "-" + mFName.get(getDriverID())[i]  + "/" + mLName.get(getDriverID())[i] + "*-INF" + mInfLName.get(getDriverID()) + "/" + dob;
                }
                gl.logCommand(logInfo,cmd);
                gl.sendCmdValidateResponse(cmd,logInfo);
                logInfo.pass("I enter passenger details");
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }


