    public void checkClassesOA(ExtentTest logInfo, String Origin, String Destination, String date, String totalpax, String COS, String airline)
    {
        String command = null;
        try {

            //A PTYLAX 10NOV-CM
            String Date = date.substring(0, 2);
            int departdate = Integer.parseInt(Date);
            int flag = 0;

            int i = departdate;

            String DateFormatted = gl.plusDaysFromTodayNew(i);
            LocalDateTime departuredate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
            String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departuredate.toLocalDate());
            mSharesStartDateSegOne.put(getDriverID(), i); //storing this value to check Other segment date should be greater than this date
            System.out.println(DateFormatted + "Date in map");
            mFlightDepartDate.put(getDriverID(), DateFormatted);
            if (airline.equalsIgnoreCase("UA"))
            {
                command = "A " + Origin + Destination + " " + departureDateFormatted + "-" + "UA";
            }
            gl.logCommand(logInfo,command);
            gl.sendCmdValidateResponse(command,logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitForProfileLoad();

            String reponse  = isharesPageObjects1.SHARES_RESPONSE.getText();

            HashMap<String, String> FltClasses = new HashMap<String,String>()
            {
                {
                    put("J", "Present");
                    put("C", "Present");
                    put("D", "Present");
                    put("Z", "Present");
                    put("P", "Present");
                    put("Y", "Present");
                    put("B", "Present");
                    put("M", "Present");
                    put("E", "Present");
                    put("U", "Present");
                    put("H", "Present");
                    put("Q", "Present");
                    put("V", "Present");
                    put("W", "Present");
                    put("S", "Present");
                    put("T", "Present");
                    put("L", "Present");
                    put("K", "Present");
                    put("G", "Present");
                    put("N", "Present");
                }
            };
            String NoOfFlights[]= reponse.split("\n");
            int count =0;
            int iteration=1;
            boolean flag1 =false;
            String flight=null;
            for( i=1;i<NoOfFlights.length;i++)
            {
                String row[]= NoOfFlights[i].split(" ");
                if(iteration==1)
                {
                    flight=row[0];
                }

                for(int j=0; j< row.length;j++)
                {
                    if(row[j].length()==2 &&  FltClasses.get(row[j].substring(0,1))!=null && Integer.parseInt(row[j].substring(1))>0  )
                    {
                        System.out.println("Class : "+row[j]);
                        count++;

                        if(count==5)
                        {
                            System.out.println("Min 5 classes with availability are there in flight "+flight);
                            flag1 =true;
                            logInfo.pass("Min 5 classes with availability are there in flight");
                            break;
                        }
                    }
                }
                if(flag1==true)
                {
                    break;
                }
                if(iteration==3)
                {
                    iteration=1;
                    count=0;
                }
                iteration++;
            }
            if(flag1==false)
            {
                System.out.println("No OA Flights have more than 5 classes as availability");
                logInfo.fail("Search for availability for first segment");
            }

            logInfo.pass("Search for availability for first segment");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

