    public void changingEntries(ExtentTest logInfo,String changeType) {

        try {

            ArrayList<String> sequence = new ArrayList<>();

//            C:D
            String command = "C:D";
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command, "SEQ  TICKET NBR",logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");


            if (changeType.equalsIgnoreCase("ChangingAmount")) {
//            C:C1/B150.00/X15.00/XY5.00
                String changingAmountCommand = "C:C1/B150.00/X15.00/XY5.00";
                gl.logCommand(logInfo, changingAmountCommand);
                gl.sendCmdValidateResponse(changingAmountCommand, "LOGGING COMPLETE",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                String rows[] = response.split("\n");
                String text[] = rows[1].split(" ");
                String tax1 = text[12];
                String tax2 = text[16];
                System.out.println("Tax1: " + tax1);
                System.out.println("Tax2: " + tax2);

                gl.sendCmdValidateResponse(command, tax1, tax2,logInfo);
            }

            else if (changeType.equalsIgnoreCase("FormOfPayment")) {
//             C:C1/$CK1234567890
                String changingFOPCommand = "C:C1/$CK1234567890";
                gl.logCommand(logInfo, changingFOPCommand);
                gl.sendCmdValidateResponse(changingFOPCommand, "LOGGING COMPLETE",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                String rows[] = response.split("\n");
                String text[] = rows[1].split(" ");
                String tax1 = text[12];
                String tax2 = text[16];
                System.out.println("Tax1: " + tax1);
                System.out.println("Tax2: " + tax2);

                gl.sendCmdValidateResponse(command, tax1, tax2,logInfo);
            }

            else if (changeType.equalsIgnoreCase("ClearEntry")) {
//             C:C<Seq Number>/CL
                gl.logCommand(logInfo, command);
                gl.sendCmdValidateResponse(command, "SEQ  TICKET NBR",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                String rows[] = response.split("\n");


                for(int i = 2; i < rows.length; i++)
                {
                    if(rows[i].contains("SUMMARY BY FOP") || rows[i].contains("|>"))
                    {
                        break;
                    }

                    String text[] = rows[i].split(" ");
                    sequence.add(text[0]);
                }

                if(sequence.size() >= 2){
                    String clearEntryCommand = "C:C" + sequence.get(0) +"/CL";
                    gl.logCommand(logInfo, clearEntryCommand);
                    gl.sendCmdValidateResponse(clearEntryCommand, "* LOGGING COMPLETE", ".00",logInfo);

                    clearEntryCommand = "C:C" + sequence.get(1) +"/CL";
                    gl.logCommand(logInfo, clearEntryCommand);
                    gl.sendCmdValidateResponse(clearEntryCommand, "* LOGGING COMPLETE", ".00",logInfo);

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command,logInfo);
                    String response1 = isharesPageObjects1.SHARES_RESPONSE.getText();
                    Assert.assertFalse(response1.contains("C:C" + sequence.get(0) +"/CL") && response1.contains("C:C" + sequence.get(1) +"/CL"));
                }
                else{
                    String clearEntryCommand = "C:C" + sequence.get(0) +"/CL";
                    gl.logCommand(logInfo, clearEntryCommand);
                    gl.sendCmdValidateResponse(clearEntryCommand, "* LOGGING COMPLETE", ".00",logInfo);

                    gl.logCommand(logInfo, command);
                    gl.sendCmdValidateResponse(command,logInfo);
                    String response1 = isharesPageObjects1.SHARES_RESPONSE.getText();
                    Assert.assertFalse(response1.contains("C:C" + sequence.get(0) +"/CL"));
                }

            }

            logInfo.pass("I change the entries");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }

    }

    public void searchDoubleAvailability(ExtentTest logInfo, String Origin, String Destination1, String Destination2, String date, String totalpax, String COS) {

        String command = null;
        try {

//            A 10DEC LAXNYC 800A 3DEN30/3ORD30/3

            String Date = date.substring(0, 2);
            int departdate = Integer.parseInt(Date);
            int flag = 0;

            for (int i = departdate; i <= departdate+5; i++) {  // loop for date

                String DateFormatted = gl.plusDaysFromTodayNew(i);
                LocalDateTime departuredate = DateUtil.formatToLocalDateTime(DateFormatted, "10:10");
                String departureDateFormatted = DateUtil.formatDateToSharesDateFormat(departuredate.toLocalDate());

                mSharesStartDateSegOne.put(getDriverID(), i); //storing this value to check Other segment date should be greater than this date
                System.out.println(DateFormatted + "Date in map");
                mFlightDepartDate.put(getDriverID(), DateFormatted);

                command = "A " + departureDateFormatted + Origin + "NYC 800A 3" + Destination1 + "30/3" + Destination2 + "30/3-UA";

                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                gl.waitForProfileLoad();

                for (int j = 1; j <= 3; j++) {  //loop for flight

                    String command2 = "N" + totalpax + COS + j; //N2Y1
                    gl.logCommand(logInfo,command2);
                    gl.sendCmdValidateResponse(command2,logInfo);
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    if (response.contains("ETKT ELIGIBLE") || response.contains("ADV PAX FLT ARRIVES TERMINAL") || response.contains("SS" + totalpax) || response.contains("NN" + totalpax)) {

                        mFlightNumber.put(getDriverID(), response.substring(6, 10).trim());
                        System.out.println("Flight number " + response.substring(6, 10));

                        flag = 1;
                        break;
                    } else {
                        gl.logCommand(logInfo,command);
                        gl.sendCmdValidateResponse(command,logInfo);
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    }
                }
                if (flag == 1) {
                    break;
                }
            }
            mOriginCity.put(getDriverID(), Origin);
//            mDestinationcity.put(getDriverID(), Destination);

            logInfo.pass("Search for double availability ");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

