    public void assignShipmentOfDifferentEquipment(ExtentTest logInfo, String status, String airline, String date) {

//        6:*A703/8JUNPTY

        String Origin = mOriginCity.get(getDriverID());
        String Destination = mDestinationcity.get(getDriverID());
        int totalPax = mFName.get(getDriverID()).length;
        String totalPassengers = Integer.toString(totalPax);
        String COS = mCOS.get(getDriverID());

        try {

            isharesPageObjects1.FORMSIZE_DROPDOWN.click();
            isharesPageObjects1.FORMSIZE_SELECT2.click();
            gl.waitForProfileLoad();
            String command = "6:*A" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                    + mOriginCity.get(getDriverID());
            gl.logCommand(logInfo,command);
            gl.sendCmdForForm2ValidateResponse(command,logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            String EqpNumber= "";
            if(isharesPageObjects1.SHARES_RESPONSE.getText().contains("SHIP ASSIGNED"))
            {

                isharesPageObjects1.FORMSIZE_DROPDOWN.click();
                isharesPageObjects1.FORMSIZE_SELECT1.click();
                searchavailabilityTakingDifferentFlt(logInfo, Origin, Destination, date, totalPassengers, COS, airline);
                gl.ignoreTRNS(logInfo);

                isharesPageObjects1.FORMSIZE_DROPDOWN.click();
                isharesPageObjects1.FORMSIZE_SELECT2.click();

                command = "6:*A" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                        + mOriginCity.get(getDriverID());
                gl.logCommand(logInfo,command);
                gl.sendCmdForForm2ValidateResponse(command,logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            }

            for(int i=0;i<isharesPageObjects1.SHARES_RESPONSE.getText().split("\n").length;i++)
            {
                if(isharesPageObjects1.SHARES_RESPONSE.getText().split("\n")[i].contains( mFlightNumber.get(getDriverID())))
                {
                    if(mFlightNumber.get(getDriverID()).length()==4)
                    {
                        EqpNumber =isharesPageObjects1.SHARES_RESPONSE.getText().split("\n")[i].split(" ")[2];
                    }
                    else
                    {
                        EqpNumber =isharesPageObjects1.SHARES_RESPONSE.getText().split("\n")[i].split(" ")[3];
                    }
                    break;
                }
            }

            System.out.println("EQUIPMENT NUMBER : "+EqpNumber);
            String equipNumbers[] = {"P", "L", "D", "9"};
            String letter = EqpNumber.substring(2);
            int index = 0;

            for(int i = 0; i < equipNumbers.length; i++){

                if(!equipNumbers[i].equalsIgnoreCase(letter)){         //if any of the equipNumbers in the array is not equal to the letter then we take that index
                    index = i;
                    break;
                }
            }

            EqpNumber = EqpNumber.substring(0,2) + equipNumbers[index];

            String command2 = "6:I*F" + EqpNumber;
            gl.logCommand(logInfo,command2);
            gl.sendCmdForForm2ValidateResponse(command2,logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            String FleetNumber = "";
            if(globalConstants.testEnv.equalsIgnoreCase("sharesCURL") || globalConstants.testEnv.equalsIgnoreCase("sharesD3URL")){
                FleetNumber = isharesPageObjects1.SHARES_RESPONSE.getText().substring(128, 132);
            }
            else{
                FleetNumber = isharesPageObjects1.SHARES_RESPONSE.getText().substring(130, 134);
            }

            System.out.println("Flight ship index " + FleetNumber);
            String command3 = "6:CA" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID())) + "\n"
                    + mFlightNumber.get(getDriverID()) + mOriginCity.get(getDriverID()) + FleetNumber;
            gl.logCommand(logInfo,command3);
            isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA.click();
            gl.copyCmdToClipboardAndPaste(command3,isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);
            isharesPageObjects1.SEND_ISHARES.click();
            gl.waitForProfileLoad();
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            String response = isharesPageObjects1.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains("SHIP NOT ASSIGNED"));

            isharesPageObjects1.FORMSIZE_DROPDOWN.click();
            isharesPageObjects1.FORMSIZE_SELECT1.click();

            if(status.equalsIgnoreCase("Accept")){
//                    6:CE441/12JULPTY.YES#B
                String command4 = "6:CE" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                        + mOriginCity.get(getDriverID()) + "." + "YES|B";

                gl.logCommand(logInfo,command4);
                gl.sendCmdValidateResponse(command4, "*SHIP ASSIGNED*",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }
            else if(status.equalsIgnoreCase("Reject")){
//                    6:CE441/12JULPTY.NO
                String command4 = "6:CE" + mFlightNumber.get(getDriverID()) + "/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                        + mOriginCity.get(getDriverID()) + "." + "NO";

                gl.logCommand(logInfo,command4);
                gl.sendCmdValidateResponse(command4, "OK", "PENDING SHIP ASSIGN/CHANGE REJECTED",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }


    public void CreateGDSPnr(ExtentTest logInfo, String PnrType, String TotalSegments, String SSRType) {
        try {

            String BaseCommand = "";

            if(SSRType.equalsIgnoreCase("CancelSegment")){
                BaseCommand = GDSPnrType(PnrType,"NA") + GDSPnrTotalPax() +  GDSPnrCancelSegments(TotalSegments);
            }
            else if(SSRType.equalsIgnoreCase("TKTLSSR")){
                GenerateUniquePnr(logInfo);
                BaseCommand = GDSPnrType(PnrType,"NA") + GDSPnrTotalPax() + GDSPnrTotalSegments(TotalSegments)+ GDSPnrTKTLSSR();
            }
            else if(SSRType.equalsIgnoreCase("BPR")){
                GenerateUniquePnr(logInfo);
                BaseCommand = GDSPnrType(PnrType,"BPR") + GDSPnrTotalPax() + GDSPnrTotalSegments(TotalSegments);
            }
            else if(SSRType.equalsIgnoreCase("FlifoIn")){
                BaseCommand = GDSPnrType(PnrType,"FlifoIn");
            }
            else if(SSRType.equalsIgnoreCase("FlifoOut")){
                BaseCommand = GDSPnrType(PnrType,"FlifoOut");
            }
            else if(SSRType.equalsIgnoreCase("ChangePaxName")){
                GenerateUniquePnr(logInfo);
                BaseCommand = GDSPnrType(PnrType,"ChangePaxName") + GDSPnrTotalPax() + GDSPnrTotalSegments("ChangePaxName");
            }
            else if(SSRType.equalsIgnoreCase("GDSPnrChangePaxName")){
                BaseCommand = GDSPnrType(PnrType,"ChangePaxName") + GDSPnrChangePaxName() + GDSPnrTotalSegments(TotalSegments);
            }
            else {
                GenerateUniquePnr(logInfo);
                BaseCommand = GDSPnrType(PnrType,"NA") + GDSPnrTotalPax() +  GDSPnrTotalSegments(TotalSegments);
            }

            isharesPageObjects1.FORMSIZE_DROPDOWN.click();
            isharesPageObjects1.FORMSIZE_SELECT24.click();

            gl.logCommand(logInfo,BaseCommand);
            System.out.println("BaseCommand " + BaseCommand);
            gl.copyCmdToClipboardAndPaste(BaseCommand,isharesPageObjects1.FORMSIZE_SELECT2_TEXTAREA);

            isharesPageObjects1.SEND_ISHARES.click();
            logInfo.pass("I passed TTY message");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            gl.waitForProfileLoad();
            String response = isharesPageObjects1.SHARES_RESPONSE.getText();
            Assert.assertTrue(response.contains("MESSAGE ACCEPTED"));
            isharesPageObjects1.FORMSIZE_DROPDOWN.click();
            isharesPageObjects1.FORMSIZE_SELECT1.click();

            if(!SSRType.equalsIgnoreCase("FlifoOut")) {
                if(!SSRType.equalsIgnoreCase("FlifoIn")){
                    gl.ignoreTRNS(logInfo);
                    gl.waitForProfileLoad();
                    gl.logCommand(logInfo,"*ER-" + mPNRNo1.get(getDriverID()));
                    gl.sendCmdValidateResponse("*ER-" + mPNRNo1.get(getDriverID()),mFName.get(getDriverID())[0].toUpperCase(),logInfo);
                    logInfo.pass("I retrive PNR for TTY message");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                    response = isharesPageObjects1.SHARES_RESPONSE.getText();
                    String pnr = response.substring(0, 6);
                    mOrderNumber.put(getDriverID(),pnr);

                    gl.logCommand(logInfo,"*" + mOrderNumber.get(getDriverID()));
                    gl.sendCmdValidateResponse("*" + mOrderNumber.get(getDriverID()),mFName.get(getDriverID())[0].toUpperCase(),logInfo);
                    logInfo.pass("I retrive PNR for TTY message");
                    logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                }

            }

        } catch (AssertionError | Exception e) {
            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }
    public String GDSPnrType(String PnrType,String SSRType) {
        String BaseCommand = "";

        if(globalConstants.testEnv.equalsIgnoreCase("sharesCURL")){
            BaseCommand = "Y" + "\n" + "PTYRMCM" + "\n"
                    + ".MUCRM" + PnrType + " 251335" + "\n"
                    + "MUC" + PnrType + " " +mPNRNo1.get(getDriverID()) + "\n";
        }
        else if(globalConstants.testEnv.equalsIgnoreCase("sharesURL")){
            BaseCommand = "Y" + "\n" + "PTYRMCM" + "\n"
                    + ".MUCRM" + PnrType + "\n"
                    + "MUC" + PnrType + " " +mPNRNo1.get(getDriverID()) + "\n";
        }

        if(SSRType.equalsIgnoreCase("BPR")){
            BaseCommand = "Y" + "\n" + "PTYRMCM" + "\n"
                    + ".MUCRM" + PnrType + " 251335" + "\n" + "BPR" + "\n"
                    + "MUC" + PnrType + " " +mPNRNo1.get(getDriverID()) + "\n";;
        }
        if(SSRType.equalsIgnoreCase("ChangePaxName")){
            BaseCommand = "Y" + "\n" + "PTYRMCM" + "\n"
                    + ".MUCRM" + PnrType + " 251335" + "\n"
                    + "MUC" + PnrType  + " " +mPNRNo1.get(getDriverID()) + "\n";
        }
        else if(SSRType.equalsIgnoreCase("FlifoIn")){

            String arrivalTime = mSharesArrivalTime.get(getDriverID());
            String meridian1 = "";
            //  2P131/07AUG IN LIM 350P
            if(arrivalTime.contains("A")) {
                arrivalTime = arrivalTime.split("A")[0];
                meridian1 = "A";
            }
            else {
                arrivalTime = arrivalTime.split("P")[0];
                meridian1 = "P";
            }
            int arriveTime = Integer.parseInt(arrivalTime);

            if(arriveTime/100 < 10)
                arriveTime = arriveTime + 100;
            else
                arriveTime = arriveTime + 1000;

            String finalArrivalTime = arriveTime + meridian1;

            BaseCommand = "Y" + "\n" + "PTYRMCM" + "\n"
                    + ".MUCRM" + PnrType + " 251335" + "\n" + "FAM" + "\n"
                    + "2P" + mFlightNumber.get(getDriverID()) + "/" +sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                    +  " IN " + mDestinationcity.get(getDriverID()) + " " + finalArrivalTime;
        }
        else if(SSRType.equalsIgnoreCase("FlifoOut")){

            String arrivalTime = mSharesArrivalTime.get(getDriverID());
            String meridian1 = "";
            //  2P0173/16SEP PRE PTY 0734A
            if(arrivalTime.contains("A")) {
                arrivalTime = arrivalTime.split("A")[0];
                meridian1 = "A";
            }
            else {
                arrivalTime = arrivalTime.split("P")[0];
                meridian1 = "P";
            }
            int arriveTime = Integer.parseInt(arrivalTime);

            if(arriveTime/100 < 10)
                arriveTime = arriveTime - 100;
            else
                arriveTime = arriveTime - 1000;

            String finalArrivalTime = arriveTime + meridian1;

            BaseCommand = "Y" + "\n" + "PTYRMCM" + "\n"
                    + ".MUCRM" + PnrType + " 251335" + "\n" + "FAM" + "\n"
                    + "2P" + mFlightNumber.get(getDriverID()) + "/" +sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                    +  " PRE " + mDestinationcity.get(getDriverID()) + " " + finalArrivalTime;
        }
        return BaseCommand;
    }

    public void GenerateUniquePnr(ExtentTest logInfo) {
//        *ER-SUSUHU

        String GDSUniquePnr = "";
        String UniquePnr = "S" + RandomStringUtils.randomAlphabetic(5).toUpperCase();
        gl.sendCmdValidateResponse("*ER-" + UniquePnr,logInfo);
        String Response = isharesPageObjects1.SHARES_RESPONSE.getText();

        int i=0;
        while(!Response.contains("NO MATCH FOUND") ){
            UniquePnr = "S" + RandomStringUtils.randomAlphabetic(5).toUpperCase();
            gl.logCommand(logInfo,"*ER-" + UniquePnr);
            gl.sendCmdValidateResponse("*ER-" + UniquePnr,logInfo);
            Response = isharesPageObjects1.SHARES_RESPONSE.getText();
            i++;
            if(i>15){
                break;
            }
        }
        mPNRNo1.put(getDriverID(),UniquePnr);
    }

