    public String GDSPnrTotalSegments(String TotalSegments) {
        String GDSPnrTotalSegments = "";
        //        CM0360Y20SEPPTYLAXNN1
        if(TotalSegments.equalsIgnoreCase("1"))
        {
            GDSPnrTotalSegments =  mAirline1.get(getDriverID()) + mFlightNumber.get(getDriverID())
                    + mCOS.get(getDriverID()) + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                    + mOriginCity.get(getDriverID()) + mDestinationcity.get(getDriverID()) + "NN" + mFName.get(getDriverID()).length;
        }
        else if(TotalSegments.equalsIgnoreCase("2"))
        {
            String GDSPnrTotalSegments1 =  mAirline1.get(getDriverID()) + mFlightNumber.get(getDriverID())
                    + mCOS.get(getDriverID()) + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()))
                    + mOriginCity.get(getDriverID()) + mDestinationcity.get(getDriverID()) +  "NN" +mFName.get(getDriverID()).length + "\n";

            String GDSPnrTotalSegments2 =  mAirline2.get(getDriverID()) + mConnectingFlightNumber.get(getDriverID())
                    + mCOS.get(getDriverID()) + sharesFormatDateFromGUI(mSharesStartDateSegTwo.get(getDriverID()))
                    + mConnectedfromCity.get(getDriverID()) + mConnecteddestinationCity.get(getDriverID()) +  "NN" +mFName.get(getDriverID()).length;
            GDSPnrTotalSegments = GDSPnrTotalSegments1 + GDSPnrTotalSegments2;
        }
        else if(TotalSegments.equalsIgnoreCase("ChangePaxName"))
        {
            GDSPnrTotalSegments =  mAirline1.get(getDriverID()) + mFlightNumber.get(getDriverID())
                    + mCOS.get(getDriverID()) + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()) + 1)
                    + mOriginCity.get(getDriverID()) + mDestinationcity.get(getDriverID()) + "NN" + mFName.get(getDriverID()).length;
        }

        boolean childPax = false;

        for(int i=0;i<mFName.get(getDriverID()).length;i++){
            if(mPaxName_PaxType.get(getDriverID()).get(mPaxNameList.get(getDriverID()).get(i)).equalsIgnoreCase("Child")
                    || mPaxName_PaxType.get(getDriverID()).get(mPaxNameList.get(getDriverID()).get(i)).equalsIgnoreCase("INF")
                    || mPaxName_PaxType.get(getDriverID()).get(mPaxNameList.get(getDriverID()).get(i)).equalsIgnoreCase("INS")){
                GDSPnrAddPaxSSR();
                childPax = true;
                break;
            }
        }
        if(childPax){
            System.out.println("GDSPnrTotalSegments " + GDSPnrTotalSegments);
            return GDSPnrTotalSegments + GDSPnrAddPaxSSR();
        }
        else{
            System.out.println("GDSPnrTotalSegments " + GDSPnrTotalSegments);
            return GDSPnrTotalSegments;
        }
    }

