            String timeLimit = mSharesDepartureTime.get(getDriverID());
            if(timeLimit.contains("A"))
                timeLimit = timeLimit.split("A")[0];
            else
                timeLimit = timeLimit.split("P")[0];

            int inputTimeLimit = Integer.parseInt(timeLimit);
            if(inputTimeLimit/100 < 10)
                inputTimeLimit = inputTimeLimit - 100;
            else
                inputTimeLimit = inputTimeLimit - 1000;

            System.out.println("Input Time Limit : " + inputTimeLimit);

            String command = "8CM" + mOriginCity.get(getDriverID()) + inputTimeLimit + "A/" + sharesFormatDateFromGUI(mSharesStartDateSegOne.get(getDriverID()));
