    public void searchavailabilityTakingDifferentFltSecondSegment(ExtentTest logInfo, String Origin, String Destination, String date, String totalpax, String COS,String airline) {
        try {
            //A PTYLAX 10NOV-CM
            String Date = date.substring(0, 2);
            int departdate = Integer.parseInt(Date);
            int flag = 0;

            String departureDateFormatted = sharesFormatDateFromGUI(mSharesStartDateSegTwo.get(getDriverID()));

//                    mSharesStartDateSegTwo.put(getDriverID(), i); //storing this value to check Other segment date should be greater than this date
            System.out.println(departureDateFormatted + "Date in map");
            mFlightDepartDate.put(getDriverID(), departureDateFormatted);

            String command = null;

            if (airline.equalsIgnoreCase("CM")) {
                command = "A " + Origin + mConnecteddestinationCity.get(getDriverID()) + " " + departureDateFormatted + "-" + "CM";
            }
            gl.logCommand(logInfo, command);
            gl.sendCmdValidateResponse(command,logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            String Response = isharesPageObjects1.SHARES_RESPONSE.getText();
            gl.checkForErrors(command,Response,logInfo);

            flightIndex.put(getDriverID(),getFlightPositions(Response,airline));

            int maxValue = 3;
            for (int j = 1; j <= maxValue; j++) {  //loop for flight

                String command2 = "N" + totalpax + COS + j; //N2Y1
                gl.logCommand(logInfo,command2);
                gl.sendCmdValidateResponse(command2,logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                String response = isharesPageObjects1.SHARES_RESPONSE.getText();
                gl.checkForErrors(command2,response,logInfo);


                if (response.contains("ETKT ELIGIBLE") && !mConnectingFlightNumber.get(getDriverID()).equalsIgnoreCase(response.substring(6,10))) {

                    mConnectingFlightNumber.put(getDriverID(), response.substring(7, 10).trim());
                    System.out.println("FFlight number " + response.substring(7, 10));
                    mCOS.put(getDriverID(),COS);
                    flag = 1;
                    break;

                } else {

                    if(j==3){
                        maxValue = 6;
                        j = 1;
                        gl.sendCmdValidateResponse("A*",logInfo);
                    }
                    else {
                        gl.logCommand(logInfo, command);
                        gl.sendCmdValidateResponse(command,logInfo);
                        logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                        gl.checkForErrors(command,isharesPageObjects1.SHARES_RESPONSE.getText(),logInfo);
                    }
                }
                if(flag==1){
                    break;
                }
            }
            logInfo.pass("Search for availability");
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);			 
              Assert.fail("This step failed.. so stopping...");			 
        }
    }

    public void modifyOASegmentTime(ExtentTest logInfo) {

//        .T1/0720P 1040P
        try {
            String meridian = null;
            String meridian1 = null;

            String departureTime = mSharesDepartureTime.get(getDriverID());
            String arrivalTime = mSharesArrivalTime.get(getDriverID());

            //For departure time
            if(departureTime.contains("A")) {
                departureTime = departureTime.split("A")[0];
                meridian = "A";
            }
            else {
                departureTime = departureTime.split("P")[0];
                meridian = "P";
            }

            System.out.println(departureTime);
            System.out.println(arrivalTime);
            int departTime = Integer.parseInt(departureTime);

            if(departTime/100 < 10)
                departTime = departTime + 4;
            else
                departTime = departTime + 4;

            //For arrival time
            if(arrivalTime.contains("A")) {
                arrivalTime = arrivalTime.split("A")[0];
                meridian1 = "A";
            }
            else {
                arrivalTime = arrivalTime.split("P")[0];
                meridian1 = "P";
            }

            int arriveTime = Integer.parseInt(arrivalTime);

            if(arriveTime/100 < 10)
                arriveTime = arriveTime + 4;
            else
                arriveTime = arriveTime + 4;

//        .T1/0720P 1040P
            String finalDepartureTime = departTime + meridian;
            String finalArrivalTime = arriveTime + meridian1;

            String command = ".T1/" + finalDepartureTime + " " + finalArrivalTime;
            gl.logCommand(logInfo,command);
            gl.sendCmdValidateResponse(command,"*",logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            logInfo.pass("I modify the OA segment time");

            gl.logCommand(logInfo, saveAndRetrieve);
            gl.sendCmdValidateResponse(saveAndRetrieve,mOrderNumber.get(getDriverID()),logInfo);
            gl.logCommand(logInfo, endAndretrieve);
            gl.sendCmdIfRequired(endAndretrieve, mOrderNumber.get(getDriverID()), "SIMULT CHGS TO PNR",logInfo);
            logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

            if(isharesPageObjects1.SHARES_RESPONSE.getText().contains("SIMULT CHGS TO PNR")){

                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse("IR", mOrderNumber.get(getDriverID()),logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");

                gl.logCommand(logInfo,command);
                gl.sendCmdValidateResponse(command,"*",logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
                logInfo.pass("I modify the OA segment time");

                gl.logCommand(logInfo, "*R");
                gl.sendCmdValidateResponse("*R", finalDepartureTime, finalArrivalTime,logInfo);
                logInfo.addScreenCaptureFromBase64String(getBase64(getDriver()), "Screenshot");
            }

        } catch (AssertionError | Exception e) {

            ExtentReportListener.testStepHandle("FAIL", getDriver(), logInfo, e);
            Assert.fail("This step failed.. so stopping...");
        }
    }

