    public List<String> getFlightPositions(String responseText, String Airline) {
        // Initialize a list to store the flight numbers
        List<String> numbers = new ArrayList<>();

        // Split the response into lines
        String[] lines = responseText.split("\n");

        // Regex to capture 3-digit flight numbers first
        String threeDigitRegex = "(\\d*)"+Airline+"\\s?(\\d{3})\\b";
        // Regex to capture 4-digit flight numbers if no 3-digit numbers are found
        String fourDigitRegex = "(\\d*)"+Airline+"\\s?(\\d{4})\\b";

        // Compile the regex for 3-digit numbers
        Pattern threeDigitPattern = Pattern.compile(threeDigitRegex);
        // Compile the regex for 4-digit numbers
        Pattern fourDigitPattern = Pattern.compile(fourDigitRegex);

        boolean foundThreeDigit = false;

        // First pass: try to find 3-digit numbers
        for (int i = 0; i < lines.length; i++) {
            Matcher matcher = threeDigitPattern.matcher(lines[i]);
            while (matcher.find()) {
                String numberLeft = matcher.group(1); // Get the captured number before CM
                numbers.add(numberLeft);
                foundThreeDigit = true;
                System.out.println("3-digit Number left of CM: " + numberLeft + " on line " + (i + 1));
            }
        }

        // If no 3-digit numbers were found, try finding 4-digit numbers
        if (!foundThreeDigit) {
            for (int i = 0; i < lines.length; i++) {
                Matcher matcher = fourDigitPattern.matcher(lines[i]);
                while (matcher.find()) {
                    String numberLeft = matcher.group(1); // Get the captured number before CM
                    numbers.add(numberLeft);
                    System.out.println("4-digit Number left of CM: " + numberLeft + " on line " + (i + 1));
                }
            }
        }

        return numbers;
    }



